// SVG 1 — COLREG LEGAL VALUE
// ══════════════════════════════════════
function ColregLegalSVG({ lang }) {
  const [sel, setSel] = useState(null);
  const items = [
    { id:"convention", icon:"📜", color:C.blue2,
      label:{fr:"Statut juridique COLREG",en:"COLREG legal status",es:"Estatus jurídico COLREG",pt:"Estatuto jurídico COLREG"},
      desc:{fr:"Convention internationale OMI (1972)\nEn vigueur : 15 juillet 1977\n168 États contractants (> 98% tonnage mondial)\n\nNATURE JURIDIQUE :\n→ Droit international incorporé dans droit national\n→ Chaque État signataire doit l'intégrer dans sa législation\n→ Valeur de loi nationale dans les États membres\n→ Applicable en haute mer + eaux territoriales\n→ Applicable MÊME en eaux intérieures si État l'a adopté\n\nHIÉRARCHIE :\nUNCLOS (Constitution maritime)\n↓ COLREG (navigation sécurisée)\n↓ Droit national (amendes, peines)",en:"IMO international convention (1972)\nIn force: July 15, 1977\n168 contracting states (98%+ world tonnage)\n\nLEGAL NATURE:\n→ International law incorporated into national law\n→ Each signatory state must integrate it into legislation\n→ Has the force of national law in member states\n→ Applicable on high seas + territorial waters\n→ Applicable in inland waters if state adopted it\n\nHIERARCHY:\nUNCLOS (Maritime Constitution)\n↓ COLREG (safe navigation)\n↓ National law (fines, penalties)",es:"Convenio internacional OMI (1972)\nEn vigor: 15 julio 1977\n168 estados contratantes (>98% tonelaje mundial)\n\nNATURALEZA JURÍDICA:\n→ Derecho internacional incorporado al derecho nacional\n→ Cada Estado signatario debe integrarlo en su legislación\n→ Fuerza de ley nacional en los Estados miembros\n→ Aplicable en alta mar + aguas territoriales",pt:"Convenção internacional IMO (1972)\nEm vigor: 15 julho 1977\n168 estados contratantes (>98% tonelagem mundial)\n\nNATUREZA JURÍDICA:\n→ Direito internacional incorporado no direito nacional\n→ Cada estado signatário deve integrá-lo na sua legislação\n→ Tem força de lei nacional nos estados membros\n→ Aplicável em alto mar + águas territoriais"}},
    { id:"liability", icon:"⚖️", color:C.red,
      label:{fr:"Responsabilité en cas d'abordage",en:"Liability in case of collision",es:"Responsabilidad en caso de abordaje",pt:"Responsabilidade em caso de abalroamento"},
      desc:{fr:"CONVENTION DE BRUXELLES 1910 :\nPartage des responsabilités selon les fautes\n\nTYPES DE RESPONSABILITÉ :\n1. Responsabilité CIVILE\n→ Dommages matériels au navire adverse\n→ Dommages corporels équipage/passagers\n→ Pollution consécutive\n→ Couverte par assurance P&I\n\n2. Responsabilité PÉNALE\n→ Si faute intentionnelle ou négligence grave\n→ Capitaine · Officier de quart\n→ Prison + amende personnelle possibles\n\n3. Responsabilité ADMINISTRATIVE\n→ Suspension ou retrait de brevet\n→ PSC · Tribunal Maritime",en:"BRUSSELS CONVENTION 1910:\nShared liability based on fault\n\nTYPES OF LIABILITY:\n1. CIVIL liability\n→ Material damage to other vessel\n→ Bodily injury crew/passengers\n→ Consequential pollution\n→ Covered by P&I insurance\n\n2. CRIMINAL liability\n→ If intentional fault or gross negligence\n→ Captain · Watch officer\n→ Prison + personal fine possible\n\n3. ADMINISTRATIVE liability\n→ Certificate suspension or revocation\n→ PSC · Maritime Tribunal",es:"CONVENIO DE BRUSELAS 1910:\nResponsabilidad compartida según las faltas\n\nTIPOS DE RESPONSABILIDAD:\n1. Responsabilidad CIVIL\n→ Daños materiales al buque adversario\n→ Daños corporales tripulación/pasajeros\n→ Contaminación consecuente\n→ Cubierta por seguro P&I\n\n2. Responsabilidad PENAL\n→ Si falta intencional o negligencia grave\n→ Capitán · Oficial de guardia\n→ Prisión + multa personal posibles\n\n3. Responsabilidad ADMINISTRATIVA\n→ Suspensión o revocación del título\n→ PSC · Tribunal Marítimo",pt:"CONVENÇÃO DE BRUXELAS 1910:\nResponsabilidade partilhada com base nas faltas\n\nTIPOS DE RESPONSABILIDADE:\n1. Responsabilidade CIVIL\n→ Danos materiais ao navio adversário\n→ Danos corporais tripulação/passageiros\n→ Poluição consequente\n→ Coberta por seguro P&I\n\n2. Responsabilidade PENAL\n→ Se falta intencional ou negligência grave\n→ Capitão · Oficial de quarto\n→ Prisão + multa pessoal possíveis\n\n3. Responsabilidade ADMINISTRATIVA\n→ Suspensão ou revogação do certificado\n→ PSC · Tribunal Marítimo"}},
    { id:"rules_key", icon:"📋", color:C.gold2,
      label:{fr:"Règles clés COLREG",en:"Key COLREG rules",es:"Reglas clave COLREG",pt:"Regras chave COLREG"},
      desc:{fr:"38 RÈGLES + 4 ANNEXES :\n\nRÈGLES FONDAMENTALES :\nRègle 5 → Veille (look-out) PERMANENTE\nRègle 6 → Vitesse de SÉCURITÉ\nRègle 7 → Risque d'abordage · radar · AIS\nRègle 8 → Manœuvre pour éviter l'abordage\nRègle 10 → DST (Dispositifs de Séparation du Trafic)\nRègle 13 → Navire qui rattrape\nRègle 16 → Navire écartant (give-way)\nRègle 17 → Navire maintenant (stand-on)\nRègle 18 → Hiérarchie des navires\nRègle 35 → Signaux sonores (brume)\n\nCHAQUE RÈGLE VIOLÉE = INFRACTION\n→ Preuve de faute dans une procédure d'abordage",en:"38 RULES + 4 ANNEXES:\n\nFUNDAMENTAL RULES:\nRule 5 → PERMANENT look-out\nRule 6 → SAFE speed\nRule 7 → Collision risk · radar · AIS\nRule 8 → Action to avoid collision\nRule 10 → TSS (Traffic Separation Schemes)\nRule 13 → Overtaking vessel\nRule 16 → Give-way vessel\nRule 17 → Stand-on vessel\nRule 18 → Vessel hierarchy\nRule 35 → Sound signals (fog)\n\nEACH RULE VIOLATED = INFRACTION\n→ Proof of fault in collision proceedings",es:"38 REGLAS + 4 ANEXOS:\n\nREGLAS FUNDAMENTALES:\nRegla 5 → Vigilancia PERMANENTE\nRegla 6 → Velocidad de SEGURIDAD\nRegla 7 → Riesgo de abordaje · radar · AIS\nRegla 8 → Maniobra para evitar el abordaje\nRegla 10 → ZTS (Zonas de Tráfico Separado)\nRegla 13 → Buque alcanzador\nRegla 16 → Buque cede el paso\nRegla 17 → Buque mantiene el rumbo\nRegla 18 → Jerarquía de los buques\nRegla 35 → Señales sonoras (niebla)",pt:"38 REGRAS + 4 ANEXOS:\n\nREGRAS FUNDAMENTAIS:\nRegra 5 → Vigilância PERMANENTE\nRegra 6 → Velocidade de SEGURANÇA\nRegra 7 → Risco de abalroamento · radar · AIS\nRegra 8 → Manobra para evitar abalroamento\nRegra 10 → ZST (Zonas de Separação de Tráfego)\nRegra 13 → Navio alcançador\nRegra 16 → Navio que cede a passagem\nRegra 17 → Navio que mantém o rumo\nRegra 18 → Hierarquia dos navios\nRegra 35 → Sinais sonoros (nevoeiro)"}},
    { id:"psc", icon:"🔍", color:C.green,
      label:{fr:"PSC & COLREG",en:"PSC & COLREG",es:"PSC & COLREG",pt:"PSC & COLREG"},
      desc:{fr:"VÉRIFICATIONS PSC LIÉES À COLREG :\n\nCERTIFICATIONS :\n→ OOW : Formation ARPA obligatoire (Règle 7)\n→ OOW : Formation ECDIS obligatoire\n→ STCW compétences de veille (Règle 5)\n\nÉQUIPEMENTS :\n→ Radar fonctionnel + ARPA (> 10 000 TB)\n→ AIS classe A opérationnel\n→ Feux de navigation conformes\n→ Matériel signaux sonores\n\nSANCTIONS PSC :\n→ Déficience équipements → correction immédiate\n→ Radar/AIS défaillant → detention navire possible\n→ Feux non conformes → detention",en:"PSC CHECKS RELATED TO COLREG:\n\nCERTIFICATIONS:\n→ OOW: Mandatory ARPA training (Rule 7)\n→ OOW: Mandatory ECDIS training\n→ STCW watchkeeping competencies (Rule 5)\n\nEQUIPMENT:\n→ Working radar + ARPA (> 10,000 GT)\n→ Class A AIS operational\n→ Compliant navigation lights\n→ Sound signal equipment\n\nPSC SANCTIONS:\n→ Equipment deficiency → immediate correction\n→ Radar/AIS failure → possible vessel detention\n→ Non-compliant lights → detention",es:"VERIFICACIONES PSC RELACIONADAS CON COLREG:\n\nCERTIFICACIONES:\n→ OOW: Formación ARPA obligatoria (Regla 7)\n→ OOW: Formación ECDIS obligatoria\n→ Competencias STCW de guardia (Regla 5)\n\nEQUIPOS:\n→ Radar funcional + ARPA (> 10.000 TB)\n→ AIS clase A operativo\n→ Luces de navegación conformes\n→ Material señales sonoras\n\nSANCIONES PSC:\n→ Deficiencia equipos → corrección inmediata\n→ Radar/AIS defectuoso → posible retención buque",pt:"VERIFICAÇÕES PSC RELACIONADAS COM COLREG:\n\nCERTIFICAÇÕES:\n→ OOW: Formação ARPA obrigatória (Regra 7)\n→ OOW: Formação ECDIS obrigatória\n→ Competências STCW de quarto (Regra 5)\n\nEQUIPAMENTOS:\n→ Radar funcional + ARPA (> 10.000 AB)\n→ AIS classe A operacional\n→ Luzes de navegação conformes\n→ Material sinais sonoros\n\nSANÇÕES PSC:\n→ Deficiência equipamentos → correção imediata\n→ Radar/AIS com defeito → possível retenção navio"},},
  ];
  const sel_ = sel!==null ? items[sel] : null;
  return (
    <div>
      <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8,marginBottom:10}}>
        {items.map((it,i)=>(
          <div key={i} onClick={()=>setSel(sel===i?null:i)}
            style={{padding:"12px 8px",borderRadius:12,cursor:"pointer",textAlign:"center",
              background:sel===i?`${it.color}22`:"rgba(255,255,255,0.04)",
              border:`1.5px solid ${sel===i?it.color:"rgba(255,255,255,0.08)"}`}}>
            <div style={{fontSize:24,marginBottom:4}}>{it.icon}</div>
            <div style={{fontSize:9,color:sel===i?it.color:C.muted,fontWeight:700,lineHeight:1.3}}>{it.label[lang]||it.label.fr}</div>
          </div>
        ))}
      </div>
      {sel_?<div style={{padding:"12px",borderRadius:14,background:`${sel_.color}12`,border:`1.5px solid ${sel_.color}44`,animation:"fadeUp 0.3s ease"}}>
        <div style={{fontSize:13,fontWeight:700,color:sel_.color,marginBottom:6}}>{sel_.icon} {sel_.label[lang]||sel_.label.fr}</div>
        <div style={{fontSize:11,color:C.white,lineHeight:1.6,whiteSpace:"pre-line"}}>{sel_.desc[lang]||sel_.desc.fr}</div>
      </div>:<div style={{textAlign:"center",padding:"10px",fontSize:11,color:C.muted}}>
        {lang==="fr"?"Touche un élément pour les détails":lang==="en"?"Tap an element for details":lang==="es"?"Toca un elemento para detalles":"Toque num elemento para detalhes"}
      </div>}
    </div>
  );
}

// ══════════════════════════════════════
// SVG 2 — COLLISION LIABILITY SIMULATOR
// ══════════════════════════════════════
function CollisionLiabilitySVG({ lang }) {
  const [scenario, setScenario] = useState(null);
  const scenarios = [
    { id:"fog", icon:"🌫️", color:C.orange,
      label:{fr:"Abordage par brume — MV Nordic Star",en:"Fog collision — MV Nordic Star",es:"Abordaje por niebla — MV Nordic Star",pt:"Abalroamento por nevoeiro — MV Nordic Star"},
      facts:{fr:"Lieu : Manche · 2018\nNavire A (MV Nordic Star) percute navire B (MV Baltic)\nVisibilité : 200 mètres\nNordic Star : pas de signal sonore depuis 15 min\nNordic Star : vitesse 14 nœuds (excessive)\nBaltic : signal sonore correct · vitesse 8 nœuds",en:"Location: English Channel · 2018\nVessel A (MV Nordic Star) hits vessel B (MV Baltic)\nVisibility: 200 meters\nNordic Star: no sound signal for 15 min\nNordic Star: speed 14 knots (excessive)\nBaltic: correct sound signal · speed 8 knots",es:"Lugar: Canal de la Mancha · 2018\nBuque A (MV Nordic Star) choca con buque B (MV Baltic)\nVisibilidad: 200 metros\nNordic Star: sin señal sonora desde hace 15 min\nNordic Star: velocidad 14 nudos (excesiva)\nBaltic: señal sonora correcta · velocidad 8 nudos",pt:"Local: Canal da Mancha · 2018\nNavio A (MV Nordic Star) embate no navio B (MV Baltic)\nVisibilidade: 200 metros\nNordic Star: sem sinal sonoro há 15 min\nNordic Star: velocidade 14 nós (excessiva)\nBaltic: sinal sonoro correto · velocidade 8 nós"},
      rules:{fr:"RÈGLES VIOLÉES (Nordic Star) :\n• Règle 35 : signal sonore brume ABSENT\n• Règle 6 : vitesse de sécurité DÉPASSÉE\n• Règle 5 : veille INSUFFISANTE\n\nRÈGLES VIOLÉES (Baltic) :\n• Aucune",en:"RULES VIOLATED (Nordic Star):\n• Rule 35: fog sound signal ABSENT\n• Rule 6: safe speed EXCEEDED\n• Rule 5: INSUFFICIENT look-out\n\nRULES VIOLATED (Baltic):\n• None",es:"REGLAS INFRINGIDAS (Nordic Star):\n• Regla 35: señal sonora niebla AUSENTE\n• Regla 6: velocidad de seguridad SUPERADA\n• Regla 5: vigilancia INSUFICIENTE\n\nREGLAS INFRINGIDAS (Baltic):\n• Ninguna",pt:"REGRAS VIOLADAS (Nordic Star):\n• Regra 35: sinal sonoro nevoeiro AUSENTE\n• Regra 6: velocidade de segurança ULTRAPASSADA\n• Regra 5: vigilância INSUFICIENTE\n\nREGRAS VIOLADAS (Baltic):\n• Nenhuma"},
      verdict:{fr:"VERDICT TRIBUNAL MARITIME :\nNordic Star : 100% responsable\nDommages : €8,5 millions\nCapitaine Nordic Star : 18 mois prison (sursis)\nBrevet suspendu 3 ans\nP&I Club Nordic Star paie intégralité",en:"MARITIME COURT VERDICT:\nNordic Star: 100% liable\nDamages: €8.5 million\nNordic Star captain: 18 months prison (suspended)\nCertificate suspended 3 years\nNordic Star P&I Club pays in full",es:"VEREDICTO TRIBUNAL MARÍTIMO:\nNordic Star: 100% responsable\nDaños: €8,5 millones\nCapitán Nordic Star: 18 meses prisión (suspendida)\nTítulo suspendido 3 años\nClub P&I Nordic Star paga íntegramente",pt:"VEREDICTO TRIBUNAL MARÍTIMO:\nNordic Star: 100% responsável\nDanos: €8,5 milhões\nCapitão Nordic Star: 18 meses prisão (suspensa)\nCertificado suspenso 3 anos\nP&I Club Nordic Star paga na totalidade"}},
    { id:"dst", icon:"🚢", color:C.purple,
      label:{fr:"Violation DST — MV Elona",en:"TSS violation — MV Elona",es:"Infracción ZTS — MV Elona",pt:"Violação ZST — MV Elona"},
      facts:{fr:"Lieu : DST Pas-de-Calais · 2020\nMV Elona navigue À CONTRE-SENS dans couloir DST\nPerçoit MV Scandic en route normale\nVisibilité bonne · Radar opérationnel\nCapitaine sous pression commerciale\n(retard + détour = coût)",en:"Location: Dover Strait TSS · 2020\nMV Elona navigates WRONG WAY in TSS lane\nMeets MV Scandic on normal route\nGood visibility · Operational radar\nCaptain under commercial pressure\n(delay + detour = cost)",es:"Lugar: ZTS Paso de Calais · 2020\nMV Elona navega EN SENTIDO CONTRARIO en carril ZTS\nEncuentra MV Scandic en ruta normal\nBuena visibilidad · Radar operativo\nCapitán bajo presión comercial\n(retraso + desvío = coste)",pt:"Local: ZST Estreito de Dover · 2020\nMV Elona navega NO SENTIDO ERRADO na faixa ZST\nEncontra MV Scandic na rota normal\nBoa visibilidade · Radar operacional\nCapitão sob pressão comercial\n(atraso + desvio = custo)"},
      rules:{fr:"RÈGLES VIOLÉES (Elona) :\n• Règle 10 : navigation dans le mauvais sens DST\n• Règle 8 : manœuvre d'évitement insuffisante\n• Règle 16 : give-way non respecté\n\nAGGRAVANT :\nDécision délibérée du capitaine\n→ Qualification PÉNALE possible",en:"RULES VIOLATED (Elona):\n• Rule 10: wrong-way DST navigation\n• Rule 8: insufficient avoiding action\n• Rule 16: give-way not respected\n\nAGGRAVATING:\nDeliberate captain decision\n→ Possible CRIMINAL qualification",es:"REGLAS INFRINGIDAS (Elona):\n• Regla 10: navegación en sentido contrario ZTS\n• Regla 8: maniobra de evitación insuficiente\n• Regla 16: ceder el paso no respetado\n\nAGRAVANTE:\nDecisión deliberada del capitán\n→ Posible calificación PENAL",pt:"REGRAS VIOLADAS (Elona):\n• Regra 10: navegação no sentido errado ZST\n• Regra 8: manobra de evitamento insuficiente\n• Regra 16: ceder a passagem não respeitado\n\nAGRAVANTE:\nDecisão deliberada do capitão\n→ Possível qualificação PENAL"},
      verdict:{fr:"VERDICT :\nElona : 85% responsable · Scandic : 15%\nAmende compagnie Elona : £500 000\nCapitaine : retrait définitif de brevet\nPoursuites pénales abandonnées (coopération)\nP&I : remboursement proportionnel",en:"VERDICT:\nElona: 85% liable · Scandic: 15%\nElona company fine: £500,000\nCaptain: permanent certificate revocation\nCriminal proceedings dropped (cooperation)\nP&I: proportional reimbursement",es:"VEREDICTO:\nElona: 85% responsable · Scandic: 15%\nMulta compañía Elona: £500.000\nCapitán: revocación definitiva del título\nAcciones penales abandonadas (cooperación)\nP&I: reembolso proporcional",pt:"VEREDICTO:\nElona: 85% responsável · Scandic: 15%\nMulta companhia Elona: £500.000\nCapitão: revogação definitiva do certificado\nAção penal abandonada (cooperação)\nP&I: reembolso proporcional"}},
    { id:"shared", icon:"⚡", color:C.red,
      label:{fr:"Faute partagée — cas complexe",en:"Shared fault — complex case",es:"Falta compartida — caso complejo",pt:"Falta partilhada — caso complexo"},
      facts:{fr:"Lieu : détroit de Malacca · 2019\nA (pétrolier) et B (cargo) en route de collision\nA = navire prioritaire (rule 18) mais ne manœuvre pas\nB = navire devant céder · tourne trop tard\nDeux erreurs simultanées",en:"Location: Strait of Malacca · 2019\nA (tanker) and B (cargo) on collision course\nA = stand-on vessel (rule 18) but doesn't maneuver\nB = give-way vessel · turns too late\nTwo simultaneous errors",es:"Lugar: Estrecho de Malaca · 2019\nA (petrolero) y B (carguero) en ruta de colisión\nA = buque mantiene (regla 18) pero no maniobra\nB = buque cede el paso · gira demasiado tarde\nDos errores simultáneos",pt:"Local: Estreito de Malaca · 2019\nA (petroleiro) e B (cargueiro) em rota de colisão\nA = navio que mantém (regra 18) mas não manobra\nB = navio que cede a passagem · vira tarde demais\nDois erros simultâneos"},
      rules:{fr:"RÈGLES VIOLÉES (A - pétrolier) :\n• Règle 17(b) : doit manœuvrer si abordage imminent\n→ Même navire prioritaire = obligation d'agir si danger immédiat\n\nRÈGLES VIOLÉES (B - cargo) :\n• Règle 16 : manœuvre trop tardive\n• Règle 8 : action d'évitement insuffisante",en:"RULES VIOLATED (A - tanker):\n• Rule 17(b): must maneuver if collision imminent\n→ Even stand-on vessel = obligation to act if immediate danger\n\nRULES VIOLATED (B - cargo):\n• Rule 16: too late maneuver\n• Rule 8: insufficient avoiding action",es:"REGLAS INFRINGIDAS (A - petrolero):\n• Regla 17(b): debe maniobrar si abordaje inminente\n→ Incluso buque mantiene = obligación de actuar si peligro inmediato\n\nREGLAS INFRINGIDAS (B - carguero):\n• Regla 16: maniobra demasiado tardía\n• Regla 8: acción de evitación insuficiente",pt:"REGRAS VIOLADAS (A - petroleiro):\n• Regra 17(b): deve manobrar se abalroamento iminente\n→ Mesmo navio que mantém = obrigação de agir se perigo imediato\n\nREGRAS VIOLADAS (B - cargueiro):\n• Regra 16: manobra demasiado tarde\n• Regra 8: ação de evitamento insuficiente"},
      verdict:{fr:"VERDICT CONVENTION BRUXELLES 1910 :\nA (pétrolier) : 40% responsable\nB (cargo) : 60% responsable\nTotal dommages : $12 millions\nA paie $4,8M · B paie $7,2M\nPrincipe : proportionnalité des fautes\nPas de poursuites pénales (fautes non intentionnelles)",en:"VERDICT BRUSSELS CONVENTION 1910:\nA (tanker): 40% liable\nB (cargo): 60% liable\nTotal damages: $12 million\nA pays $4.8M · B pays $7.2M\nPrinciple: fault proportionality\nNo criminal proceedings (unintentional faults)",es:"VEREDICTO CONVENIO BRUSELAS 1910:\nA (petrolero): 40% responsable\nB (carguero): 60% responsable\nDaños totales: $12 millones\nA paga $4,8M · B paga $7,2M\nPrincipio: proporcionalidad de las faltas\nSin acciones penales (faltas no intencionales)",pt:"VEREDICTO CONVENÇÃO BRUXELAS 1910:\nA (petroleiro): 40% responsável\nB (cargueiro): 60% responsável\nDanos totais: $12 milhões\nA paga $4,8M · B paga $7,2M\nPrincípio: proporcionalidade das faltas\nSem ação penal (faltas não intencionais)"},},
  ];
  const sc = scenario!==null ? scenarios[scenario] : null;
  return (
    <div>
      {scenarios.map((s,i)=>(
        <button key={i} onClick={()=>setScenario(scenario===i?null:i)} style={{
          width:"100%",marginBottom:8,padding:"10px 14px",borderRadius:12,cursor:"pointer",textAlign:"left",
          background:scenario===i?`${s.color}22`:"rgba(255,255,255,0.04)",
          border:`1.5px solid ${scenario===i?s.color:"rgba(255,255,255,0.08)"}`,
          display:"flex",alignItems:"center",gap:10,
        }}>
          <span style={{fontSize:22}}>{s.icon}</span>
          <div style={{flex:1}}>
            <div style={{fontSize:11,fontWeight:700,color:scenario===i?s.color:C.muted}}>{s.label[lang]||s.label.fr}</div>
            <div style={{fontSize:9,color:C.muted,marginTop:2}}>{lang==="fr"?"Voir le dossier complet →":lang==="en"?"See full case →":lang==="es"?"Ver el caso completo →":"Ver o caso completo →"}</div>
          </div>
          <span style={{fontSize:12,color:C.muted}}>{scenario===i?"▲":"▼"}</span>
        </button>
      ))}
      {sc&&(
        <div style={{padding:"12px",borderRadius:14,background:`${sc.color}10`,border:`1.5px solid ${sc.color}44`,animation:"fadeUp 0.3s ease"}}>
          <div style={{fontSize:10,color:C.muted,fontWeight:700,marginBottom:4}}>📁 {lang==="fr"?"DOSSIER":lang==="en"?"CASE FILE":lang==="es"?"EXPEDIENTE":"PROCESSO"}</div>
          <div style={{fontSize:10,color:C.white,lineHeight:1.6,whiteSpace:"pre-line",marginBottom:8,padding:"7px",borderRadius:8,background:"rgba(0,0,0,0.3)"}}>{sc.facts[lang]||sc.facts.fr}</div>
          <div style={{fontSize:10,color:sc.color,fontWeight:700,marginBottom:4}}>⚖️ {lang==="fr"?"RÈGLES VIOLÉES":lang==="en"?"RULES VIOLATED":lang==="es"?"REGLAS INFRINGIDAS":"REGRAS VIOLADAS"}</div>
          <div style={{fontSize:10,color:C.white,lineHeight:1.6,whiteSpace:"pre-line",marginBottom:8}}>{sc.rules[lang]||sc.rules.fr}</div>
          <div style={{padding:"8px 10px",borderRadius:8,background:`${sc.color}15`,border:`1px solid ${sc.color}33`,fontSize:10,color:C.white,lineHeight:1.6,whiteSpace:"pre-line"}}>
            🔨 {sc.verdict[lang]||sc.verdict.fr}
          </div>
        </div>
      )}
    </div>
  );
}

// ══════════════════════════════════════
// SVG 3 — FAULT ANALYSIS TOOL
// ══════════════════════════════════════
function FaultAnalysisSVG({ lang }) {
  const [faults, setFaults] = useState({});
  const rules = [
    { id:"r5", rule:"5", color:C.red,
      label:{fr:"Règle 5 — Veille",en:"Rule 5 — Look-out",es:"Regla 5 — Vigilancia",pt:"Regra 5 — Vigilância"},
      impact:{fr:"GRAVE · Défaut de veille = faute quasi-automatique en cas d'abordage · Juge maritime présume la faute si veille insuffisante",en:"SERIOUS · Failure to keep look-out = near-automatic fault in collision · Maritime judge presumes fault if insufficient look-out",es:"GRAVE · Falta de vigilancia = falta casi automática en caso de abordaje · El juez marítimo presume la falta si la vigilancia es insuficiente",pt:"GRAVE · Falta de vigilância = falta quase automática em caso de abalroamento · O juiz marítimo presume a falta se a vigilância for insuficiente"}},
    { id:"r6", rule:"6", color:C.orange,
      label:{fr:"Règle 6 — Vitesse sécurité",en:"Rule 6 — Safe speed",es:"Regla 6 — Velocidad seguridad",pt:"Regra 6 — Velocidade segurança"},
      impact:{fr:"GRAVE · Vitesse excessive en brume = faute majeure · Le juge évalue selon : visibilité, densité trafic, maniabilité du navire · Pas de limite fixe = appréciation judiciaire",en:"SERIOUS · Excessive speed in fog = major fault · Judge evaluates based on: visibility, traffic density, vessel maneuverability · No fixed limit = judicial assessment",es:"GRAVE · Velocidad excesiva en niebla = falta mayor · El juez evalúa según: visibilidad, densidad tráfico, maniobrabilidad del buque · Sin límite fijo = apreciación judicial",pt:"GRAVE · Velocidade excessiva em nevoeiro = falta maior · O juiz avalia segundo: visibilidade, densidade tráfego, manobrabilidade do navio · Sem limite fixo = apreciação judicial"}},
    { id:"r7", rule:"7", color:C.purple,
      label:{fr:"Règle 7 — Risque abordage",en:"Rule 7 — Risk of collision",es:"Regla 7 — Riesgo abordaje",pt:"Regra 7 — Risco abalroamento"},
      impact:{fr:"IMPORTANT · Utiliser tous moyens disponibles (radar, AIS, visuel) · Ne pas se fier uniquement à l'AIS · CPA/TCPA doivent être calculés · Défaillance radar = revenir à la prudence absolue",en:"IMPORTANT · Use all available means (radar, AIS, visual) · Do not rely solely on AIS · CPA/TCPA must be calculated · Radar failure = revert to utmost caution",es:"IMPORTANTE · Usar todos los medios disponibles (radar, AIS, visual) · No fiarse solo del AIS · CPA/TCPA deben calcularse · Fallo del radar = volver a la máxima prudencia",pt:"IMPORTANTE · Usar todos os meios disponíveis (radar, AIS, visual) · Não depender apenas do AIS · CPA/TCPA devem ser calculados · Falha do radar = regressar à máxima prudência"}},
    { id:"r16", rule:"16", color:C.teal,
      label:{fr:"Règle 16 — Give-way",en:"Rule 16 — Give-way",es:"Regla 16 — Ceder el paso",pt:"Regra 16 — Ceder a passagem"},
      impact:{fr:"CRITIQUE · Le navire give-way DOIT prendre une manœuvre large et nette · Micro-ajustements insuffisants · Manœuvre tardive = aggravation de la faute · Juge : 'trop peu, trop tard'",en:"CRITICAL · Give-way vessel MUST take ample and clear action · Minor adjustments insufficient · Late maneuver = fault aggravation · Judge: 'too little, too late'",es:"CRÍTICO · El buque cede el paso DEBE tomar una maniobra amplia y clara · Micro-ajustes insuficientes · Maniobra tardía = agravamiento de la falta · Juez: 'demasiado poco, demasiado tarde'",pt:"CRÍTICO · O navio que cede a passagem DEVE tomar uma manobra ampla e clara · Micro-ajustes insuficientes · Manobra tardia = agravamento da falta · Juiz: 'demasiado pouco, demasiado tarde'"}},
  ];
  const toggle = (id) => setFaults(f=>({...f,[id]:!f[id]}));
  const count = Object.values(faults).filter(Boolean).length;
  const colors = [C.green, C.yellow, C.orange, C.red];
  const liability = count===0?0:count===1?25:count===2?60:count===3?85:100;

  return (
    <div>
      <div style={{marginBottom:10,fontSize:10,color:C.muted,textAlign:"center"}}>
        {lang==="fr"?"Cochez les règles violées — calculez la responsabilité":lang==="en"?"Check violated rules — calculate liability":lang==="es"?"Marque las reglas infringidas — calcula la responsabilidad":"Marque as regras violadas — calcule a responsabilidade"}
      </div>
      {rules.map((r,i)=>(
        <div key={r.id} onClick={()=>toggle(r.id)} style={{
          display:"flex",alignItems:"center",gap:10,padding:"9px 12px",
          borderRadius:10,marginBottom:6,cursor:"pointer",
          background:faults[r.id]?`${r.color}15`:"rgba(255,255,255,0.04)",
          border:`1.5px solid ${faults[r.id]?r.color:"rgba(255,255,255,0.08)"}`}}>
          <div style={{width:24,height:24,borderRadius:6,
            background:faults[r.id]?r.color:"rgba(255,255,255,0.08)",
            border:`1.5px solid ${faults[r.id]?r.color:"rgba(255,255,255,0.2)"}`,
            display:"flex",alignItems:"center",justifyContent:"center",
            fontSize:12,color:C.white,fontWeight:700,flexShrink:0}}>
            {faults[r.id]?"✓":""}
          </div>
          <div style={{flex:1}}>
            <div style={{fontSize:11,fontWeight:700,color:faults[r.id]?r.color:C.muted}}>{r.label[lang]||r.label.fr}</div>
            {faults[r.id]&&<div style={{fontSize:9,color:r.color,lineHeight:1.3,marginTop:2}}>{r.impact[lang]||r.impact.fr}</div>}
          </div>
        </div>
      ))}
      <div style={{marginTop:10,padding:"10px 12px",borderRadius:12,
        background:`${colors[count]||C.red}15`,border:`1px solid ${colors[count]||C.red}44`}}>
        <div style={{display:"flex",justifyContent:"space-between",marginBottom:6}}>
          <div style={{fontSize:11,color:colors[count]||C.red,fontWeight:700}}>
            {lang==="fr"?"Responsabilité estimée":lang==="en"?"Estimated liability":lang==="es"?"Responsabilidad estimada":"Responsabilidade estimada"}
          </div>
          <div style={{fontSize:14,fontWeight:700,color:colors[count]||C.red}}>{liability}%</div>
        </div>
        <div style={{height:6,borderRadius:3,background:"rgba(255,255,255,0.08)",overflow:"hidden"}}>
          <div style={{height:"100%",width:`${liability}%`,background:colors[count]||C.red,transition:"width 0.4s"}}/>
        </div>
        <div style={{fontSize:9,color:C.muted,marginTop:4}}>
          {count===0?(lang==="fr"?"Aucune règle violée = 0% responsabilité":lang==="en"?"No rule violated = 0% liability":lang==="es"?"Ninguna regla infringida = 0% responsabilidad":"Nenhuma regra violada = 0% responsabilidade")
          :count>=3?(lang==="fr"?"Fautes multiples graves = responsabilité quasi totale":lang==="en"?"Multiple serious faults = near-total liability":lang==="es"?"Faltas múltiples graves = responsabilidad casi total":"Faltas múltiplas graves = responsabilidade quase total")
          :(lang==="fr"?"Partage selon Convention Bruxelles 1910":lang==="en"?"Sharing per Brussels Convention 1910":lang==="es"?"Reparto según Convenio Bruselas 1910":"Repartição segundo Convenção de Bruxelas 1910")}
        </div>
      </div>
    </div>
  );
}

