// SVG 4 — UNCLOS / JURISDICTION
// ══════════════════════════════════════
function JurisdictionSVG({ lang }) {
  const [zone, setZone] = useState(null);
  const zones = [
    { id:"internal", icon:"🏭", color:C.red, pct:8,
      label:{fr:"Eaux intérieures",en:"Internal waters",es:"Aguas interiores",pt:"Águas interiores"},
      jurisdiction:{fr:"Souveraineté TOTALE de l'État côtier\nCOLREG peut être complété par réglementation locale\nÉtat côtier = compétence exclusive\nAucun droit de passage innocent\nEx : ports · rivières · rades",en:"TOTAL sovereignty of coastal state\nCOLREG can be supplemented by local regulations\nCoastal state = exclusive jurisdiction\nNo right of innocent passage\nEx: ports · rivers · roadsteads",es:"Soberanía TOTAL del Estado ribereño\nCOLREG puede complementarse con reglamentación local\nEstado ribereño = competencia exclusiva\nSin derecho de paso inocente\nEj: puertos · ríos · radas",pt:"Soberania TOTAL do Estado costeiro\nCOLREG pode ser complementado por regulamentação local\nEstado costeiro = competência exclusiva\nSem direito de passagem inocente\nEx: portos · rios · ancoradouros"}},
    { id:"territorial", icon:"🚩", color:C.orange, pct:20,
      label:{fr:"Mer territoriale (12 milles)",en:"Territorial sea (12 miles)",es:"Mar territorial (12 millas)",pt:"Mar territorial (12 milhas)"},
      jurisdiction:{fr:"Souveraineté État côtier · COLREG applicable\nDroit de passage innocent des navires étrangers\nÉtat côtier peut poursuivre infractions COLREG\nBase légale : UNCLOS Article 21 + 27\nÉtat côtier peut instaurer couloirs de navigation obligatoires",en:"Coastal state sovereignty · COLREG applicable\nRight of innocent passage for foreign vessels\nCoastal state can prosecute COLREG violations\nLegal basis: UNCLOS Articles 21 + 27\nCoastal state can establish mandatory shipping lanes",es:"Soberanía Estado ribereño · COLREG aplicable\nDerecho de paso inocente de los buques extranjeros\nEstado ribereño puede enjuiciar infracciones COLREG\nBase legal: UNCLOS Artículos 21 + 27\nEstado ribereño puede establecer corredores de navegación obligatorios",pt:"Soberania Estado costeiro · COLREG aplicável\nDireito de passagem inocente de navios estrangeiros\nEstado costeiro pode processar infrações COLREG\nBase legal: UNCLOS Artigos 21 + 27\nEstado costeiro pode estabelecer corredores de navegação obrigatórios"}},
    { id:"eez", icon:"🌊", color:C.blue2, pct:40,
      label:{fr:"ZEE (200 milles)",en:"EEZ (200 miles)",es:"ZEE (200 millas)",pt:"ZEE (200 milhas)"},
      jurisdiction:{fr:"Droits économiques État côtier\nCOLREG pleinement applicable\nÉtat côtier : surveillance navigation · DST\nPas de souveraineté complète (liberté navigation)\nBase légale : UNCLOS Article 58\nÉtat côtier peut signaler violations à l'État du pavillon",en:"Coastal state economic rights\nCOLREG fully applicable\nCoastal state: navigation surveillance · TSS\nNo full sovereignty (freedom of navigation)\nLegal basis: UNCLOS Article 58\nCoastal state can report violations to flag state",es:"Derechos económicos del Estado ribereño\nCOLREG plenamente aplicable\nEstado ribereño: vigilancia navegación · ZTS\nSin soberanía completa (libertad de navegación)\nBase legal: UNCLOS Artículo 58\nEstado ribereño puede comunicar infracciones al Estado de pabellón",pt:"Direitos económicos do Estado costeiro\nCOLREG plenamente aplicável\nEstado costeiro: vigilância navegação · ZST\nSem soberania completa (liberdade de navegação)\nBase legal: UNCLOS Artigo 58\nEstado costeiro pode comunicar violações ao Estado de bandeira"}},
    { id:"high", icon:"🌍", color:C.green, pct:32,
      label:{fr:"Haute mer",en:"High seas",es:"Alta mar",pt:"Alto mar"},
      jurisdiction:{fr:"Liberté de navigation TOTALE\nCOLREG applicable à tous les navires\nSeul l'État du PAVILLON peut poursuivre\n(sauf piraterie · esclavage · trafic drogue)\nBase légale : UNCLOS Article 92\nPas d'intervention État tiers sauf accord\nAccidents : compétence État du pavillon + État du port suivant",en:"TOTAL freedom of navigation\nCOLREG applicable to all vessels\nOnly FLAG STATE can prosecute\n(except piracy · slavery · drug trafficking)\nLegal basis: UNCLOS Article 92\nNo third-state intervention except by agreement\nAccidents: flag state jurisdiction + next port state",es:"Libertad de navegación TOTAL\nCOLREG aplicable a todos los buques\nSolo el Estado de PABELLÓN puede enjuiciar\n(excepto piratería · esclavitud · tráfico de drogas)\nBase legal: UNCLOS Artículo 92\nSin intervención de terceros estados salvo acuerdo\nAccidentes: competencia Estado pabellón + Estado puerto siguiente",pt:"Liberdade de navegação TOTAL\nCOLREG aplicável a todos os navios\nApenas o Estado de BANDEIRA pode processar\n(exceto pirataria · escravidão · tráfico de droga)\nBase legal: UNCLOS Artigo 92\nSem intervenção de terceiros estados salvo acordo\nAcidentes: competência Estado bandeira + Estado porto seguinte"},},
  ];
  const zone_ = zone!==null ? zones[zone] : null;
  return (
    <div>
      <div style={{display:"flex",height:16,borderRadius:8,overflow:"hidden",marginBottom:10,gap:2}}>
        {zones.map((z,i)=>(
          <div key={i} onClick={()=>setZone(zone===i?null:i)}
            style={{flex:z.pct,background:zone===i?z.color:`${z.color}66`,cursor:"pointer",
              display:"flex",alignItems:"center",justifyContent:"center",transition:"all 0.2s"}}>
            <span style={{fontSize:7,color:C.white,fontWeight:700,opacity:zone===i?1:0.6}}>
              {z.pct}%
            </span>
          </div>
        ))}
      </div>
      <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:6,marginBottom:10}}>
        {zones.map((z,i)=>(
          <button key={i} onClick={()=>setZone(zone===i?null:i)} style={{
            padding:"8px 6px",borderRadius:10,cursor:"pointer",textAlign:"center",
            background:zone===i?`${z.color}22`:"rgba(255,255,255,0.04)",
            border:`1.5px solid ${zone===i?z.color:"rgba(255,255,255,0.08)"}`,
          }}>
            <div style={{fontSize:16}}>{z.icon}</div>
            <div style={{fontSize:8,color:zone===i?z.color:C.muted,fontWeight:700,lineHeight:1.3,marginTop:2}}>{z.label[lang]||z.label.fr}</div>
          </button>
        ))}
      </div>
      {zone_?<div style={{padding:"12px",borderRadius:14,background:`${zone_.color}12`,border:`1.5px solid ${zone_.color}44`,animation:"fadeUp 0.3s ease"}}>
        <div style={{fontSize:13,fontWeight:700,color:zone_.color,marginBottom:6}}>{zone_.icon} {zone_.label[lang]||zone_.label.fr}</div>
        <div style={{fontSize:11,color:C.white,lineHeight:1.6,whiteSpace:"pre-line"}}>{zone_.jurisdiction[lang]||zone_.jurisdiction.fr}</div>
      </div>:<div style={{textAlign:"center",padding:"10px",fontSize:11,color:C.muted}}>
        {lang==="fr"?"Touche une zone maritime pour la juridiction COLREG":lang==="en"?"Tap a maritime zone for COLREG jurisdiction":lang==="es"?"Toca una zona marítima para la jurisdicción COLREG":"Toque numa zona marítima para a jurisdição COLREG"}
      </div>}
    </div>
  );
}

