// ACCIDENT CASE
// ══════════════════════════════════════
function AccidentCase({ lang }) {
  const [exp,setExp]=useState(false);
  const d={
    fr:{title:"Abordage MV Alraigo / MV Urquiola — Baie de Biscaye (2014)",teaser:"Cargo/pétrolier · Brume · Règle 35 violée · Responsabilité partagée · €15M dommages",what:"Le cargo MV Alraigo et le pétrolier MV Urquiola entrent en collision dans la Baie de Biscaye par visibilité réduite (brume dense). Les deux navires émettaient des signaux sonores mais aucun ne réduisait sa vitesse. L'Alraigo virait à bâbord (mauvaise manœuvre) au lieu de tribord (prescrit par COLREG Règle 14). Les deux capitaines comparaissent devant le Tribunal Maritime de Bilbao.",cause:"• Alraigo : Règle 14 violée (virage à bâbord face à face)\n• Alraigo : Règle 6 violée (vitesse non réduite dans la brume)\n• Urquiola : Règle 6 violée (vitesse excessive)\n• Urquiola : Règle 17(b) violée (n'a pas manœuvré malgré danger imminent)\n• Les deux : Règle 5 insuffisamment appliquée (veille)",lessons:"✓ Règle 14 = TOUJOURS tribord à tribord en route opposée\n✓ Règle 17(b) = même navire prioritaire doit manœuvrer si collision imminente\n✓ Convention Bruxelles 1910 = partage des responsabilités proportionnel\n✓ Résultat : Alraigo 60% · Urquiola 40% · Total €15M\n✓ Les deux capitaines : suspension de brevet 2 ans",link:"🔗 Lien L5 COLREG Juridique : COLREG n'est pas qu'un code de navigation — c'est le fondement de toute procédure judiciaire après un abordage. Chaque règle violée est une faute prouvée devant le tribunal maritime."},
    en:{title:"Collision MV Alraigo / MV Urquiola — Bay of Biscay (2014)",teaser:"Cargo/tanker · Fog · Rule 35 violated · Shared liability · €15M damages",what:"The cargo vessel MV Alraigo and tanker MV Urquiola collide in the Bay of Biscay in reduced visibility (dense fog). Both vessels were emitting sound signals but neither reduced speed. Alraigo turned to port (wrong maneuver) instead of starboard (prescribed by COLREG Rule 14). Both captains appeared before the Maritime Tribunal of Bilbao.",cause:"• Alraigo: Rule 14 violated (port turn head-on)\n• Alraigo: Rule 6 violated (speed not reduced in fog)\n• Urquiola: Rule 6 violated (excessive speed)\n• Urquiola: Rule 17(b) violated (didn't maneuver despite imminent danger)\n• Both: Rule 5 insufficiently applied (look-out)",lessons:"✓ Rule 14 = ALWAYS starboard to starboard when head-on\n✓ Rule 17(b) = even stand-on vessel must maneuver if collision imminent\n✓ Brussels Convention 1910 = proportional shared liability\n✓ Result: Alraigo 60% · Urquiola 40% · Total €15M\n✓ Both captains: 2-year certificate suspension",link:"🔗 L5 COLREG Legal Link: COLREG is not just a navigation code — it is the foundation of all legal proceedings after a collision. Each rule violated is a proven fault before the maritime tribunal."},
    es:{title:"Abordaje MV Alraigo / MV Urquiola — Golfo de Vizcaya (2014)",teaser:"Carguero/petrolero · Niebla · Regla 35 infringida · Responsabilidad compartida · €15M daños",what:"El carguero MV Alraigo y el petrolero MV Urquiola colisionan en el Golfo de Vizcaya con visibilidad reducida (niebla densa). Ambos buques emitían señales sonoras pero ninguno reducía la velocidad. El Alraigo viró a babor (maniobra incorrecta) en lugar de a estribor (prescrito por COLREG Regla 14).",cause:"• Alraigo: Regla 14 infringida (virada a babor proa con proa)\n• Alraigo: Regla 6 infringida (velocidad no reducida en la niebla)\n• Urquiola: Regla 6 infringida (velocidad excesiva)\n• Urquiola: Regla 17(b) infringida (no maniobró pese al peligro inminente)\n• Ambos: Regla 5 aplicada insuficientemente",lessons:"✓ Regla 14 = SIEMPRE estribor con estribor en ruta opuesta\n✓ Regla 17(b) = incluso buque mantiene debe maniobrar si abordaje inminente\n✓ Convenio Bruselas 1910 = reparto de responsabilidades proporcional\n✓ Resultado: Alraigo 60% · Urquiola 40% · Total €15M\n✓ Ambos capitanes: suspensión de título 2 años",link:"🔗 Vínculo L5: COLREG no es solo un código de navegación — es el fundamento de todo proceso judicial tras un abordaje."},
    pt:{title:"Abalroamento MV Alraigo / MV Urquiola — Golfo da Biscaia (2014)",teaser:"Cargueiro/petroleiro · Nevoeiro · Regra 35 violada · Responsabilidade partilhada · €15M danos",what:"O cargueiro MV Alraigo e o petroleiro MV Urquiola colidem no Golfo da Biscaia com visibilidade reduzida (nevoeiro denso). Ambos os navios emitiam sinais sonoros mas nenhum reduzia a velocidade. O Alraigo virou a bombordo (manobra errada) em vez de estibordo (prescrito pela COLREG Regra 14).",cause:"• Alraigo: Regra 14 violada (viragem a bombordo proa a proa)\n• Alraigo: Regra 6 violada (velocidade não reduzida no nevoeiro)\n• Urquiola: Regra 6 violada (velocidade excessiva)\n• Urquiola: Regra 17(b) violada (não manobrou apesar do perigo iminente)\n• Ambos: Regra 5 insuficientemente aplicada",lessons:"✓ Regra 14 = SEMPRE estibordo com estibordo em rota oposta\n✓ Regra 17(b) = mesmo navio que mantém deve manobrar se abalroamento iminente\n✓ Convenção Bruxelas 1910 = partilha proporcional de responsabilidades\n✓ Resultado: Alraigo 60% · Urquiola 40% · Total €15M\n✓ Ambos capitães: suspensão de certificado 2 anos",link:"🔗 Vínculo L5: O COLREG não é apenas um código de navegação — é o fundamento de todo processo judicial após um abalroamento."},
  };
  const c=d[lang]||d.fr;
  return(
    <div style={{background:"rgba(192,57,43,0.08)",border:`1.5px solid ${C.red}44`,borderRadius:18,overflow:"hidden"}}>
      <div style={{padding:"14px 16px",cursor:"pointer"}} onClick={()=>setExp(v=>!v)}>
        <div style={{display:"flex",alignItems:"center",gap:10}}>
          <span style={{fontSize:22}}>⚠️</span>
          <div style={{flex:1}}><div style={{fontSize:13,fontWeight:700,color:C.red,marginBottom:2}}>{c.title}</div><div style={{fontSize:11,color:C.muted,lineHeight:1.4}}>{c.teaser}</div></div>
          <span style={{fontSize:14,color:C.muted}}>{exp?"▲":"▼"}</span>
        </div>
      </div>
      {exp&&<div style={{padding:"0 16px 16px"}}>
        <div style={{fontSize:12,color:C.white,lineHeight:1.7,marginBottom:10}}>{c.what}</div>
        <div style={{fontSize:11,color:C.red,fontWeight:700,marginBottom:5,fontFamily:"'Cinzel',serif"}}>CAUSES</div>
        <div style={{fontSize:12,color:C.white,lineHeight:1.7,whiteSpace:"pre-line",marginBottom:10}}>{c.cause}</div>
        <div style={{fontSize:11,color:C.green,fontWeight:700,marginBottom:5,fontFamily:"'Cinzel',serif"}}>{lang==="fr"?"LEÇONS":lang==="en"?"LESSONS":lang==="es"?"LECCIONES":"LIÇÕES"}</div>
        <div style={{fontSize:12,color:C.white,lineHeight:1.7,whiteSpace:"pre-line",marginBottom:10}}>{c.lessons}</div>
        <div style={{padding:"10px 12px",borderRadius:10,background:"rgba(201,146,42,0.1)",border:`1px solid ${C.gold}33`,fontSize:11,color:C.gold2,lineHeight:1.6}}>{c.link}</div>
      </div>}
    </div>
  );
}

