// EXERCISE
// ══════════════════════════════════════
function Exercise1({ lang, t }) {
  const [ans,setAns]=useState({q1:"",q2:"",q3:""});
  const [showC,setShowC]=useState(false);
  const qs={
    fr:[
      {id:"q1",q:"La Convention de Bruxelles de 1910 régit quoi ?\n(Répondre : 2 mots max)",correct:"responsabilité abordage"},
      {id:"q2",q:"En haute mer, quel État peut poursuivre les violations COLREG ?\n(Répondre : État du pavillon ou État du port)",correct:"État du pavillon"},
      {id:"q3",q:"Règle COLREG 17(b) : même le navire prioritaire doit manœuvrer si ?\n(Répondre : 2 mots)",correct:"collision imminente"},
    ],
    en:[
      {id:"q1",q:"The Brussels Convention of 1910 governs what?\n(Answer: max 2 words)",correct:"collision liability"},
      {id:"q2",q:"On the high seas, which state can prosecute COLREG violations?\n(Answer: flag state or port state)",correct:"flag state"},
      {id:"q3",q:"COLREG Rule 17(b): even the stand-on vessel must maneuver if?\n(Answer: 2 words)",correct:"collision imminent"},
    ],
    es:[
      {id:"q1",q:"¿El Convenio de Bruselas de 1910 regula qué?\n(Responder: máx 2 palabras)",correct:"responsabilidad abordaje"},
      {id:"q2",q:"En alta mar, ¿qué Estado puede enjuiciar las infracciones COLREG?\n(Responder: Estado pabellón o Estado puerto)",correct:"Estado pabellón"},
      {id:"q3",q:"COLREG Regla 17(b): incluso el buque mantiene debe maniobrar si ?\n(Responder: 2 palabras)",correct:"abordaje inminente"},
    ],
    pt:[
      {id:"q1",q:"A Convenção de Bruxelas de 1910 rege o quê?\n(Responder: máx 2 palavras)",correct:"responsabilidade abalroamento"},
      {id:"q2",q:"Em alto mar, que Estado pode processar as violações COLREG?\n(Responder: Estado bandeira ou Estado porto)",correct:"Estado bandeira"},
      {id:"q3",q:"COLREG Regra 17(b): mesmo o navio que mantém deve manobrar se ?\n(Responder: 2 palavras)",correct:"abalroamento iminente"},
    ],
  };
  const list=qs[lang]||qs.fr;
  const chk=(q,val)=>{
    const v=val.trim().toLowerCase();
    const c=q.correct.toLowerCase();
    return v.includes(c.split(" ")[0])||v.includes(c.split(" ")[1]||"");
  };
  return(
    <div>
      <div style={{background:"rgba(0,0,0,0.4)",borderRadius:12,padding:"10px 12px",marginBottom:12,border:`1px solid ${C.blue2}44`,fontSize:11,color:C.gold2,lineHeight:1.6}}>
        {lang==="fr"?"💡 Rappels : Bruxelles 1910 = responsabilité abordage · Haute mer = État du pavillon · Règle 17b = collision imminente"
        :lang==="en"?"💡 Reminders: Brussels 1910 = collision liability · High seas = flag state · Rule 17b = imminent collision"
        :lang==="es"?"💡 Recordatorios: Bruselas 1910 = responsabilidad abordaje · Alta mar = Estado pabellón · Regla 17b = abordaje inminente"
        :"💡 Lembretes: Bruxelas 1910 = responsabilidade abalroamento · Alto mar = Estado bandeira · Regra 17b = abalroamento iminente"}
      </div>
      {list.map((q,i)=>(
        <div key={q.id} style={{marginBottom:12}}>
          <div style={{fontSize:12,color:C.white,marginBottom:6,lineHeight:1.5,whiteSpace:"pre-line",fontWeight:600}}>{i+1}. {q.q}</div>
          <input type="text" value={ans[q.id]} onChange={e=>setAns(a=>({...a,[q.id]:e.target.value}))} placeholder="?"
            style={{width:"100%",padding:"10px",borderRadius:10,background:"rgba(255,255,255,0.07)",border:`1px solid ${showC?(chk(q,ans[q.id])?C.green:C.red):C.border}`,color:C.white,fontSize:14,fontFamily:"monospace",fontWeight:700,textAlign:"center",boxSizing:"border-box"}}/>
          {showC&&<div style={{fontSize:11,marginTop:4,fontWeight:600,color:chk(q,ans[q.id])?C.green:C.red}}>{chk(q,ans[q.id])?"✓":`✗ → ${q.correct}`}</div>}
        </div>
      ))}
      {showC&&<div style={{padding:"12px",borderRadius:12,background:"rgba(30,138,74,0.1)",border:`1px solid ${C.green}44`,fontSize:11,color:C.white,lineHeight:1.7,marginBottom:10}}>
        {lang==="fr"?"✅ Q1: Responsabilité abordage (Convention Bruxelles 1910 = partage des torts)\n✅ Q2: État du pavillon (seul compétent en haute mer · UNCLOS Art.92)\n✅ Q3: Collision imminente (Règle 17b = exception à la règle du stand-on)"
        :lang==="en"?"✅ Q1: Collision liability (Brussels Convention 1910 = sharing of blame)\n✅ Q2: Flag state (sole jurisdiction on high seas · UNCLOS Art.92)\n✅ Q3: Imminent collision (Rule 17b = exception to stand-on rule)"
        :"✅ Q1: Responsabilidad abordaje · Q2: Estado pabellón · Q3: Abordaje inminente"}
      </div>}
      <button onClick={()=>setShowC(v=>!v)} style={{width:"100%",padding:"11px 0",borderRadius:12,background:showC?"rgba(30,138,74,0.2)":"rgba(201,146,42,0.15)",border:`1px solid ${showC?C.green:C.gold}44`,color:showC?C.green:C.gold2,fontSize:12,fontWeight:700,cursor:"pointer",fontFamily:"'Cinzel',serif"}}>
        {showC?t.hideCorr:t.showCorr}
      </button>
    </div>
  );
}


const QUIZ = {
  fr:[
    {q:"La Convention de Bruxelles de 1910 (droit des abordages) établit quel principe fondamental ?",opts:["Responsabilité exclusive du navire le plus grand","Partage de responsabilité proportionnel aux fautes commises par chaque navire","Toujours 50/50 entre les deux navires","Responsabilité exclusive du navire qui a été percuté"],correct:1,expl:"Convention de Bruxelles 1910 (COLREG de la responsabilité) = partage des responsabilités proportionnel aux fautes. Si navire A commet 3 violations COLREG et navire B en commet 1, le tribunal peut décider A = 75% responsable, B = 25%. Chaque navire paie sa part des dommages selon ce pourcentage. Base de tous les procès maritimes d'abordage."},
    {q:"En haute mer, quel État a compétence pour poursuivre les violations COLREG ?",opts:["L'État côtier le plus proche","L'État du PAVILLON exclusivement (avec exceptions limitées)","L'État du port suivant","L'OMI directement"],correct:1,expl:"En haute mer (UNCLOS Article 92) : seul l'État du PAVILLON a compétence pour poursuivre les infractions COLREG. Exceptions : piraterie (compétence universelle), trafic de drogue, transport d'esclaves. Un État côtier peut surveiller et signaler, mais ne peut pas arrêter un navire étranger en haute mer sauf flagrant délit de piraterie."},
    {q:"La Règle 17(b) COLREG est-elle applicable au navire prioritaire (stand-on) ?",opts:["Non — le navire stand-on n'a jamais à manœuvrer","Oui — si la collision devient imminente malgré le respect de la règle, le navire stand-on DOIT manœuvrer","Oui — mais seulement par visibilité réduite","Non — seulement le navire give-way doit agir"],correct:1,expl:"Règle 17(b) COLREG = exception cruciale. Normalement le navire stand-on (prioritaire) maintient cap et vitesse (Règle 17a). MAIS si la collision devient inévitable malgré le comportement correct, le navire stand-on DOIT prendre l'action la plus efficace pour éviter la collision. Ne pas agir alors = violation de la Règle 17(b) = faute juridique."},
    {q:"Une violation de la Règle 5 COLREG (veille) a quelles conséquences juridiques ?",opts:["Aucune — c'est une recommandation","Présomption de faute quasi-automatique en cas d'abordage — charge de la preuve inversée pour le navire défaillant","Simple avertissement administratif","Responsabilité uniquement civile"],correct:1,expl:"Règle 5 COLREG (veille permanente) = règle fondamentale. En cas d'abordage, si le navire A n'avait pas de veille correcte = le tribunal PRÉSUME la faute de A. La charge de la preuve s'inverse : c'est A qui doit prouver que son manque de veille n'a pas contribué à l'abordage. En pratique quasi-impossible. Défaut de veille = principale cause judiciaire d'abordages."},
    {q:"Un navire en DST (Dispositif de Séparation du Trafic) qui navigue dans le mauvais couloir voit sa responsabilité civile ...",opts:["Réduite car il a fait de son mieux","Aggravée — violation délibérée de la Règle 10 = circonstance aggravante judiciaire","Inchangée — seul l'abordage compte","Inexistante en haute mer"],correct:1,expl:"Violation DST (Règle 10) = infraction grave avec circonstances aggravantes. Raisons : 1) La Règle 10 est claire et sans ambiguïté. 2) Le DST est visible sur toutes les cartes. 3) La décision de naviguer à contre-sens est souvent délibérée (gain de temps). Un tribunal maritime considère une violation DST délibérée comme une faute grave → % de responsabilité élevé."},
  ],
  en:[
    {q:"The Brussels Convention of 1910 (collision law) establishes what fundamental principle?",opts:["Exclusive liability of the largest vessel","Liability sharing proportional to faults committed by each vessel","Always 50/50 between the two vessels","Exclusive liability of the vessel that was struck"],correct:1,expl:"Brussels Convention 1910 (collision liability) = proportional liability sharing based on faults. If vessel A commits 3 COLREG violations and vessel B commits 1, the court may decide A = 75% liable, B = 25%. Each vessel pays its share of damages according to this percentage. Basis of all maritime collision trials."},
    {q:"On the high seas, which state has jurisdiction to prosecute COLREG violations?",opts:["The nearest coastal state","The FLAG STATE exclusively (with limited exceptions)","The next port state","IMO directly"],correct:1,expl:"On the high seas (UNCLOS Article 92): only the FLAG STATE has jurisdiction to prosecute COLREG violations. Exceptions: piracy (universal jurisdiction), drug trafficking, slave transport. A coastal state can monitor and report, but cannot stop a foreign vessel on the high seas except in flagrant piracy."},
    {q:"Is COLREG Rule 17(b) applicable to the stand-on vessel?",opts:["No — stand-on vessel never has to maneuver","Yes — if collision becomes imminent despite compliance, stand-on vessel MUST maneuver","Yes — but only in reduced visibility","No — only give-way vessel must act"],correct:1,expl:"COLREG Rule 17(b) = crucial exception. Normally stand-on vessel maintains course and speed (Rule 17a). BUT if collision becomes unavoidable despite correct behavior, stand-on vessel MUST take most effective action to avoid collision. Failing to act = Rule 17(b) violation = legal fault."},
    {q:"A violation of COLREG Rule 5 (look-out) has what legal consequences?",opts:["None — it's a recommendation","Near-automatic fault presumption in case of collision — reversed burden of proof for the failing vessel","Simple administrative warning","Civil liability only"],correct:1,expl:"COLREG Rule 5 (permanent look-out) = fundamental rule. In case of collision, if vessel A didn't maintain proper look-out = court PRESUMES A's fault. Burden of proof reverses: A must prove its lack of look-out didn't contribute to the collision. In practice nearly impossible. Failure to keep look-out = main judicial cause of collisions."},
    {q:"A vessel in a TSS (Traffic Separation Scheme) navigating in the wrong lane sees its civil liability ...",opts:["Reduced as it did its best","Aggravated — deliberate Rule 10 violation = judicial aggravating circumstance","Unchanged — only the collision matters","Non-existent on high seas"],correct:1,expl:"TSS violation (Rule 10) = serious offense with aggravating circumstances. Reasons: 1) Rule 10 is clear and unambiguous. 2) TSS is visible on all charts. 3) The decision to navigate wrong-way is often deliberate (time saving). A maritime tribunal considers a deliberate TSS violation as serious fault → high % liability."},
  ],
  es:[
    {q:"¿El Convenio de Bruselas de 1910 (derecho de abordajes) establece qué principio fundamental?",opts:["Responsabilidad exclusiva del buque más grande","Reparto de responsabilidad proporcional a las faltas cometidas por cada buque","Siempre 50/50 entre los dos buques","Responsabilidad exclusiva del buque que fue embestido"],correct:1,expl:"Convenio de Bruselas 1910 = reparto de responsabilidades proporcional a las faltas. Si buque A comete 3 infracciones COLREG y buque B comete 1, el tribunal puede decidir A = 75% responsable, B = 25%. Cada buque paga su parte de los daños según este porcentaje. Base de todos los procesos judiciales marítimos de abordaje."},
    {q:"En alta mar, ¿qué Estado tiene competencia para enjuiciar las infracciones COLREG?",opts:["El Estado ribereño más cercano","El Estado de PABELLÓN exclusivamente (con excepciones limitadas)","El Estado del próximo puerto","La OMI directamente"],correct:1,expl:"En alta mar (CONVEMAR Artículo 92): solo el Estado de PABELLÓN tiene competencia para enjuiciar las infracciones COLREG. Excepciones: piratería (competencia universal), tráfico de drogas, transporte de esclavos. Un Estado ribereño puede vigilar y notificar, pero no puede detener un buque extranjero en alta mar."},
    {q:"¿La Regla 17(b) COLREG es aplicable al buque que mantiene el rumbo (stand-on)?",opts:["No — el buque stand-on nunca tiene que maniobrar","Sí — si el abordaje se vuelve inminente a pesar del cumplimiento, el buque stand-on DEBE maniobrar","Sí — pero solo con visibilidad reducida","No — solo el buque cede el paso debe actuar"],correct:1,expl:"COLREG Regla 17(b) = excepción crucial. Normalmente el buque stand-on mantiene rumbo y velocidad (Regla 17a). PERO si el abordaje se vuelve inevitable a pesar del comportamiento correcto, el buque stand-on DEBE tomar la acción más eficaz para evitar el abordaje. No actuar = infracción Regla 17(b) = falta jurídica."},
    {q:"¿Una infracción de la Regla 5 COLREG (vigilancia) tiene qué consecuencias jurídicas?",opts:["Ninguna — es una recomendación","Presunción de falta casi automática en caso de abordaje — inversión de la carga de la prueba para el buque incumplidor","Simple advertencia administrativa","Responsabilidad únicamente civil"],correct:1,expl:"COLREG Regla 5 (vigilancia permanente) = regla fundamental. En caso de abordaje, si el buque A no tenía una vigilancia correcta = el tribunal PRESUME la falta de A. La carga de la prueba se invierte: es A quien debe probar que su falta de vigilancia no contribuyó al abordaje. En la práctica casi imposible."},
    {q:"Un buque en ZTS (Zona de Tráfico Separado) que navega en el carril equivocado ve su responsabilidad civil ...",opts:["Reducida porque hizo todo lo posible","Agravada — infracción deliberada de la Regla 10 = circunstancia agravante judicial","Sin cambios — solo cuenta el abordaje","Inexistente en alta mar"],correct:1,expl:"Infracción ZTS (Regla 10) = infracción grave con circunstancias agravantes. Razones: 1) La Regla 10 es clara e inequívoca. 2) La ZTS es visible en todas las cartas. 3) La decisión de navegar en sentido contrario suele ser deliberada. Un tribunal marítimo considera una infracción ZTS deliberada como falta grave → alto % de responsabilidad."},
  ],
  pt:[
    {q:"A Convenção de Bruxelas de 1910 (direito dos abalroamentos) estabelece que princípio fundamental?",opts:["Responsabilidade exclusiva do navio maior","Partilha de responsabilidade proporcional às faltas cometidas por cada navio","Sempre 50/50 entre os dois navios","Responsabilidade exclusiva do navio que foi embatido"],correct:1,expl:"Convenção de Bruxelas 1910 = partilha de responsabilidades proporcional às faltas. Se navio A comete 3 violações COLREG e navio B comete 1, o tribunal pode decidir A = 75% responsável, B = 25%. Cada navio paga a sua parte dos danos segundo esta percentagem. Base de todos os processos judiciais marítimos de abalroamento."},
    {q:"Em alto mar, que Estado tem competência para processar as violações COLREG?",opts:["O Estado costeiro mais próximo","O Estado de BANDEIRA exclusivamente (com exceções limitadas)","O Estado do próximo porto","A IMO diretamente"],correct:1,expl:"Em alto mar (UNCLOS Artigo 92): apenas o Estado de BANDEIRA tem competência para processar as violações COLREG. Exceções: pirataria (competência universal), tráfico de droga, transporte de escravos. Um Estado costeiro pode vigiar e comunicar, mas não pode deter um navio estrangeiro em alto mar."},
    {q:"A COLREG Regra 17(b) é aplicável ao navio que mantém o rumo (stand-on)?",opts:["Não — o navio stand-on nunca tem de manobrar","Sim — se o abalroamento se tornar iminente apesar do cumprimento, o navio stand-on DEVE manobrar","Sim — mas apenas com visibilidade reduzida","Não — apenas o navio que cede a passagem deve agir"],correct:1,expl:"COLREG Regra 17(b) = exceção crucial. Normalmente o navio stand-on mantém rumo e velocidade (Regra 17a). MAS se o abalroamento se tornar inevitável apesar do comportamento correto, o navio stand-on DEVE tomar a ação mais eficaz para evitar o abalroamento. Não agir = violação Regra 17(b) = falta jurídica."},
    {q:"Uma violação da Regra 5 COLREG (vigilância) tem que consequências jurídicas?",opts:["Nenhuma — é uma recomendação","Presunção de falta quase automática em caso de abalroamento — inversão do ónus da prova para o navio faltoso","Simples aviso administrativo","Responsabilidade apenas civil"],correct:1,expl:"COLREG Regra 5 (vigilância permanente) = regra fundamental. Em caso de abalroamento, se o navio A não tinha vigilância correta = o tribunal PRESUME a falta de A. O ónus da prova inverte-se: é A que deve provar que a sua falta de vigilância não contribuiu para o abalroamento. Na prática quase impossível."},
    {q:"Um navio em ZST (Zona de Separação de Tráfego) que navega na faixa errada vê a sua responsabilidade civil ...",opts:["Reduzida pois fez o seu melhor","Agravada — violação deliberada da Regra 10 = circunstância agravante judicial","Inalterada — apenas o abalroamento importa","Inexistente em alto mar"],correct:1,expl:"Violação ZST (Regra 10) = infração grave com circunstâncias agravantes. Razões: 1) A Regra 10 é clara e sem ambiguidade. 2) A ZST é visível em todas as cartas. 3) A decisão de navegar no sentido errado é frequentemente deliberada. Um tribunal marítimo considera uma violação ZST deliberada como falta grave → alta % de responsabilidade."},
  ],
};

const BANK = {
  fr:[
    {q:"Qu'est-ce que le 'Tribunal Maritime' (Marine Court / MAIB) ?",opts:["Un tribunal commercial ordinaire","Juridiction spécialisée dans les accidents maritimes — enquête sur les causes, tire les leçons, peut suspendre les brevets","Un tribunal OMI","Un arbitrage commercial"],correct:1,expl:"Tribunal Maritime (ex. MAIB UK, BEA-mer France, BSU Allemagne) = autorité d'enquête sur les accidents maritimes. Rôle : analyser les causes des accidents, émettre des recommandations de sécurité, tirer les leçons. Peut : suspendre les brevets, identifier les responsabilités. Différent du tribunal pénal (crime) et du tribunal civil (dommages). Base des procédures après abordage."},
    {q:"Qu'est-ce que le 'CPA' (Closest Point of Approach) dans le contexte juridique COLREG ?",opts:["Un accord commercial entre navires","Distance minimale de rapprochement calculée par radar — si CPA trop faible = risque d'abordage · obligation d'agir (Règle 8)","Un certificat de navigation","Un protocole de communication"],correct:1,expl:"CPA (Closest Point of Approach) = distance minimale prévue entre deux navires. Calculé par radar ARPA. Si CPA est inférieur à un seuil sûr = risque d'abordage → obligation légale d'agir (Règle 7 + 8 COLREG). En cas d'abordage : le tribunal vérifie si le CPA a été calculé et si des actions ont été prises. Ne pas calculer le CPA = violation de la Règle 7 = faute."},
    {q:"Qu'est-ce que la 'règle d'or' des abordages (Golden Rule) ?",opts:["Toujours donner la priorité aux grands navires","Ne jamais hésiter à manœuvrer — l'action tardive est pire que l'absence d'action · la 'dernière minute' est toujours impardonnable","Toujours réduire la vitesse en premier","Appeler la VHF avant de manœuvrer"],correct:1,expl:"Règle d'or maritime abordages : l'action tardive est juridiquement et techniquement pire que l'absence d'action anticipée. Un navire qui manœuvre au dernier moment perturbe les calculs de l'autre. Jurisprudence : 'trop peu, trop tard' = circonstance aggravante. La règle 8 COLREG exige une manœuvre franche, large et effectuée tôt."},
    {q:"Qu'est-ce que la 'preuve radar' en cas de procédure d'abordage ?",opts:["Une photo du radar","Enregistrements radar (ARPA) et AIS conservés après l'accident — permettent de reconstituer les trajectoires et identifier les violations COLREG","Un rapport écrit de l'officier","Un document de l'OMI"],correct:1,expl:"Preuve radar en procédure d'abordage : les données ARPA et AIS sont des preuves cruciales. VDR (Voyage Data Recorder) = boîte noire maritime (SOLAS Chap. V) conserve 12h de données radar, cap, vitesse, VHF. En cas d'abordage : VDR saisi par les enquêteurs. Permet de reconstituer exactement les trajectoires et d'identifier qui a violé quelles règles COLREG."},
    {q:"Qu'est-ce que l'expertise maritime (marine surveyor) dans une procédure d'abordage ?",opts:["Un inspecteur PSC","Expert indépendant mandaté par les assureurs P&I ou les tribunaux pour évaluer les dommages et analyser les causes de l'abordage","Un membre de l'OMI","Un expert maritime commercial"],correct:1,expl:"Marine surveyor = expert maritime indépendant. En cas d'abordage : mandaté par P&I Club, assureur cargo, ou tribunal. Missions : évaluer les dommages matériels, analyser les causes (violations COLREG), reconstituer les trajectoires (données AIS/radar), préparer un rapport d'expertise technique. Son rapport est une pièce centrale du dossier judiciaire."},
    {q:"Qu'est-ce que le 'derecho de paso inocente' (droit de passage innocent) dans le contexte COLREG ?",opts:["Un accord bilatéral","Droit des navires étrangers de traverser la mer territoriale d'un État (12 milles) sans autorisation — à condition de ne pas menacer la paix","Un droit commercial","Un droit de pêche"],correct:1,expl:"Droit de passage innocent (UNCLOS Art.17-32) = droit fondamental. Navire étranger peut traverser mer territoriale (12 milles) SANS autorisation préalable SI : passage continu et rapide, non préjudiciable à la paix et sécurité. COLREG pleinement applicable durant le passage. L'État côtier peut établir des couloirs de navigation obligatoires dans sa mer territoriale."},
    {q:"Qu'est-ce que le 'tonnage limitation' (limitation de responsabilité) en droit maritime ?",opts:["Limite de poids de la cargaison","Droit de l'armateur de limiter sa responsabilité civile à un montant basé sur le tonnage du navire — Convention LLMC 1976","Une limite de vitesse","Une limite d'assurance"],correct:1,expl:"Limitation de responsabilité = Convention LLMC 1976 (Limitation of Liability for Maritime Claims). L'armateur peut limiter sa responsabilité à un montant calculé selon le tonnage (ex: 400 DTS/TB pour dommages aux biens). Exceptions : faute intentionnelle du propriétaire. Importance : même pour des dommages de plusieurs millions, l'armateur peut ne payer qu'une fraction. P&I Club gère souvent la procédure."},
    {q:"Qu'est-ce que le 'témoignage de l'officier de quart' comme preuve dans un abordage ?",opts:["Une preuve sans valeur légale","Témoignage crucial mais limité — l'officier peut invoquer son droit au silence · ses déclarations peuvent être retenues contre lui","Un document OMI","Un simple rapport de bord"],correct:1,expl:"Témoignage OOW en procédure d'abordage = preuve essentielle mais risquée. L'officier de quart est souvent le principal témoin. Il peut : faire une déclaration, refuser de témoigner (droit au silence). Ses déclarations initiales aux enquêteurs peuvent être retournées contre lui au pénal. Recommandation : consulter un avocat maritime AVANT de faire une déclaration."},
    {q:"Qu'est-ce que la 'clause Himalaya' dans le contexte maritime ?",opts:["Une clause météo","Extension de la protection contractuelle accordée à l'armateur aux officiers et membres d'équipage — empêche les tiers de poursuivre directement l'équipage","Un accord de navigation polaire","Un contrat d'assurance spécial"],correct:1,expl:"Clause Himalaya = extension de la limitation de responsabilité. Permet aux officiers et membres d'équipage de bénéficier des mêmes protections que l'armateur (limitation de responsabilité, délais de prescription). Sans clause Himalaya : un tiers (ex : chargeur) pourrait poursuivre directement l'officier de quart pour violation COLREG. Avec la clause : l'officier est protégé par les mêmes limites."},
    {q:"Qu'est-ce que la 'prescription' en droit maritime des abordages ?",opts:["Un médicament de bord","Délai légal au-delà duquel une action judiciaire après abordage ne peut plus être intentée — généralement 2 ans (Convention Bruxelles 1910)","Un protocole de navigation","Une règle COLREG"],correct:1,expl:"Prescription (statute of limitations) en droit des abordages : Convention Bruxelles 1910 = délai de prescription de 2 ans à partir de l'abordage. Après 2 ans = action judiciaire irrecevable (sauf exceptions). Importance pour les P&I Clubs : déclaration d'abordage IMMÉDIATE pour ne pas perdre les délais. Certains droits nationaux prévoient des délais différents."},
    {q:"Qu'est-ce que la 'collision avoidance' comme obligation légale COLREG ?",opts:["Une recommandation de l'OMI","Obligation légale de prendre TOUTES les mesures nécessaires pour éviter l'abordage — même si cela implique de violer temporairement une autre règle COLREG","Un système technique","Un protocole de communication"],correct:1,expl:"Collision avoidance = obligation légale absolue (Règle 8 COLREG). Le navire DOIT prendre toutes les mesures pour éviter la collision, même si cela nécessite de violer temporairement une autre règle (ex : dépasser la vitesse habituelle en virage d'urgence). Jurisprudence : le juge accepte les 'manœuvres in extremis' comme défense si la situation était imposée par le comportement fautif de l'autre navire."},
    {q:"Qu'est-ce que la 'responsabilité de la compagnie' pour les violations COLREG de son capitaine ?",opts:["La compagnie n'est jamais responsable","La compagnie peut être tenue civilement responsable si elle n'a pas fourni formation, instructions, équipements ou procédures adéquates — responsbilité ISM","Seul le capitaine est responsable","La compagnie est toujours responsable à 100%"],correct:1,expl:"Responsabilité compagnie pour violations COLREG : Code ISM (SOLAS IX) = la compagnie doit s'assurer que ses navires et officiers respectent les règles. Si violation COLREG → la compagnie peut être poursuivie si elle n'a pas : fourni des officiers formés (STCW), établi des procédures SMS claires, fourni les équipements nécessaires. Lien COLREG + ISM + STCW = responsabilité enchaînée."},
    {q:"Qu'est-ce que le 'Right of Hot Pursuit' lié à COLREG ?",opts:["Un droit de navigation rapide","Droit de l'État côtier de poursuivre en haute mer un navire qui a violé COLREG dans ses eaux — poursuite doit être continue et immédiate","Un droit douanier","Un droit de pêche"],correct:1,expl:"Hot pursuit + COLREG : UNCLOS Art.111 donne le droit à l'État côtier de poursuivre en haute mer un navire qui a violé ses lois (y compris COLREG) dans ses eaux territoriales. La poursuite doit : commencer dans les eaux territoriales, être immédiate et continue, cesser si le navire entre dans les eaux d'un État tiers. Limité aux violations dans les eaux sous juridiction."},
    {q:"Qu'est-ce qu'un 'Lloyd's Open Form' (LOF) en cas d'abordage grave ?",opts:["Un formulaire d'assurance standard","Contrat de sauvetage d'urgence signé 'no cure no pay' — utilisé quand un navire est en danger après abordage · rémunération = % de la valeur sauvée","Un type de police d'assurance","Un formulaire OMI"],correct:1,expl:"Lloyd's Open Form (LOF) = contrat de sauvetage maritime standard. Utilisé quand un navire est en péril (après abordage, échouage, incendie). Principe 'no cure no pay' = le sauveteur n'est payé que s'il réussit. Rémunération : % de la valeur sauvée (navire + cargaison), déterminé par arbitrage Lloyd's. Signé en situation d'urgence. Base juridique de la plupart des opérations de sauvetage après abordage."},
    {q:"Qu'est-ce que la 'navigation imprudente' (reckless navigation) en droit pénal maritime ?",opts:["Une infraction civile mineure","Qualification pénale aggravée quand un officier navigue avec une imprudence tellement grave qu'elle dépasse la simple négligence — entraîne des poursuites pénales personnelles","Une infraction administrative","Une règle COLREG"],correct:1,expl:"Navigation imprudente (reckless navigation) = qualification pénale. En droit français : 'mise en danger délibérée d'autrui'. En droit anglais : 'gross negligence manslaughter' si mort. Conditions : faute délibérée ou d'une gravité telle qu'elle s'assimile à de l'intention. Exemples : naviguer dans le mauvais couloir DST par gain de temps, utiliser l'autopilote sans veille en zone dense. Peine : prison ferme + retrait définitif de brevet."},
  ],
  en:[
    {q:"What is the 'Maritime Tribunal' (Marine Court / MAIB)?",opts:["An ordinary commercial court","Jurisdiction specializing in maritime accidents — investigates causes, draws lessons, can suspend certificates","An IMO tribunal","Commercial arbitration"],correct:1,expl:"Maritime Tribunal (e.g. MAIB UK, BEA-mer France, BSU Germany) = maritime accident investigation authority. Role: analyze accident causes, issue safety recommendations, draw lessons. Can: suspend certificates, identify responsibilities. Different from criminal court (crime) and civil court (damages). Basis of post-collision proceedings."},
    {q:"What is 'CPA' (Closest Point of Approach) in the COLREG legal context?",opts:["A commercial agreement between vessels","Minimum approach distance calculated by radar — if CPA too close = collision risk · obligation to act (Rule 8)","A navigation certificate","A communication protocol"],correct:1,expl:"CPA (Closest Point of Approach) = minimum predicted distance between two vessels. Calculated by ARPA radar. If CPA below safe threshold = collision risk → legal obligation to act (COLREG Rules 7 + 8). In case of collision: court checks if CPA was calculated and if action was taken. Failing to calculate CPA = Rule 7 violation = fault."},
    {q:"What is the 'Golden Rule' of collision avoidance?",opts:["Always give priority to large vessels","Never hesitate to maneuver — late action is worse than anticipated action · 'last minute' is always unforgivable","Always reduce speed first","Call VHF before maneuvering"],correct:1,expl:"Maritime collision golden rule: late action is legally and technically worse than early anticipated action. A vessel maneuvering at the last moment disrupts the other's calculations. Jurisprudence: 'too little, too late' = aggravating circumstance. COLREG Rule 8 requires an ample, clear, early maneuver."},
    {q:"What is 'radar evidence' in collision proceedings?",opts:["A photo of the radar","Radar (ARPA) and AIS recordings preserved after the accident — allow reconstruction of trajectories and identification of COLREG violations","An officer's written report","An IMO document"],correct:1,expl:"Radar evidence in collision proceedings: ARPA and AIS data are crucial evidence. VDR (Voyage Data Recorder) = maritime black box (SOLAS Ch. V) stores 12h of radar data, course, speed, VHF. In case of collision: VDR seized by investigators. Allows exact reconstruction of trajectories and identification of which COLREG rules were violated by whom."},
    {q:"What is a 'marine surveyor' in a collision proceeding?",opts:["A PSC inspector","Independent expert mandated by P&I insurers or courts to assess damages and analyze collision causes","An IMO member","A commercial maritime expert"],correct:1,expl:"Marine surveyor = independent maritime expert. In case of collision: mandated by P&I Club, cargo insurer, or court. Missions: assess material damage, analyze causes (COLREG violations), reconstruct trajectories (AIS/radar data), prepare technical expert report. Report is central evidence in judicial proceedings."},
    {q:"What is the 'right of innocent passage' in the COLREG context?",opts:["A bilateral agreement","Right of foreign vessels to traverse a state's territorial sea (12 miles) without authorization — provided they don't threaten peace","A commercial right","A fishing right"],correct:1,expl:"Right of innocent passage (UNCLOS Art.17-32) = fundamental right. Foreign vessel can traverse territorial sea (12 miles) WITHOUT prior authorization IF: continuous and expeditious passage, not prejudicial to peace and security. COLREG fully applicable during passage. Coastal state can establish mandatory shipping lanes in its territorial sea."},
    {q:"What is 'tonnage limitation' (limitation of liability) in maritime law?",opts:["A cargo weight limit","Shipowner's right to limit civil liability to an amount based on vessel tonnage — LLMC Convention 1976","A speed limit","An insurance limit"],correct:1,expl:"Limitation of liability = LLMC Convention 1976 (Limitation of Liability for Maritime Claims). Shipowner can limit liability to amount calculated by tonnage (e.g. 400 SDR/GT for property damage). Exceptions: intentional fault of the owner. Importance: even for multi-million damages, shipowner may pay only a fraction. P&I Club often manages the procedure."},
    {q:"What is 'watch officer testimony' as evidence in a collision?",opts:["Evidence with no legal value","Crucial but limited testimony — officer can invoke right to silence · statements can be used against them","An IMO document","A simple deck log"],correct:1,expl:"OOW testimony in collision proceedings = essential but risky evidence. Watch officer is often the main witness. They can: make a statement, refuse to testify (right to silence). Initial statements to investigators can be used against them in criminal proceedings. Recommendation: consult maritime lawyer BEFORE making a statement."},
    {q:"What is the 'Himalaya Clause' in the maritime context?",opts:["A weather clause","Extension of contractual protection granted to the shipowner to officers and crew — prevents third parties from suing crew directly","A polar navigation agreement","A special insurance contract"],correct:1,expl:"Himalaya Clause = extension of liability limitation. Allows officers and crew to benefit from same protections as shipowner (liability limitation, prescription periods). Without Himalaya clause: a third party (e.g. shipper) could sue the watch officer directly for COLREG violation. With the clause: officer is protected by the same limits."},
    {q:"What is 'prescription' (statute of limitations) in maritime collision law?",opts:["A ship's medicine","Legal time limit beyond which post-collision legal action can no longer be brought — generally 2 years (Brussels Convention 1910)","A navigation protocol","A COLREG rule"],correct:1,expl:"Prescription in collision law: Brussels Convention 1910 = 2-year prescription period from the collision. After 2 years = legal action inadmissible (with exceptions). Importance for P&I Clubs: IMMEDIATE collision declaration to avoid missing deadlines. Some national laws provide different timeframes."},
    {q:"What is 'collision avoidance' as a COLREG legal obligation?",opts:["An IMO recommendation","Legal obligation to take ALL necessary measures to avoid collision — even if temporarily violating another COLREG rule","A technical system","A communication protocol"],correct:1,expl:"Collision avoidance = absolute legal obligation (COLREG Rule 8). Vessel MUST take all measures to avoid collision, even if temporarily violating another rule (e.g. exceeding normal speed in emergency turn). Jurisprudence: judge accepts 'in extremis maneuvers' as defense if situation was imposed by other vessel's faulty behavior."},
    {q:"What is the 'company's responsibility' for COLREG violations by its captain?",opts:["Company is never responsible","Company can be held civilly liable if it didn't provide adequate training, instructions, equipment or procedures — ISM responsibility","Only the captain is responsible","Company is always 100% liable"],correct:1,expl:"Company responsibility for COLREG violations: ISM Code (SOLAS IX) = company must ensure its vessels and officers comply with rules. If COLREG violation → company can be pursued if it didn't: provide trained officers (STCW), establish clear SMS procedures, provide necessary equipment. COLREG + ISM + STCW link = chained responsibility."},
    {q:"What is the 'Right of Hot Pursuit' related to COLREG?",opts:["A right to navigate fast","Right of coastal state to pursue on high seas a vessel that violated COLREG in its waters — pursuit must be continuous and immediate","A customs right","A fishing right"],correct:1,expl:"Hot pursuit + COLREG: UNCLOS Art.111 gives coastal state the right to pursue on high seas a vessel that violated its laws (including COLREG) in its territorial waters. Pursuit must: begin in territorial waters, be immediate and continuous, cease if vessel enters third-state waters. Limited to violations in waters under jurisdiction."},
    {q:"What is a 'Lloyd's Open Form' (LOF) in case of serious collision?",opts:["A standard insurance form","Emergency salvage contract signed 'no cure no pay' — used when vessel is endangered after collision · remuneration = % of value saved","A type of insurance policy","An IMO form"],correct:1,expl:"Lloyd's Open Form (LOF) = standard maritime salvage contract. Used when vessel is in peril (after collision, grounding, fire). 'No cure no pay' principle = salvor only paid if successful. Remuneration: % of value saved (vessel + cargo), determined by Lloyd's arbitration. Signed in emergency. Legal basis of most salvage operations after collision."},
    {q:"What is 'reckless navigation' in maritime criminal law?",opts:["A minor civil offense","Aggravated criminal qualification when an officer navigates with negligence so serious it goes beyond simple negligence — leads to personal criminal prosecution","An administrative offense","A COLREG rule"],correct:1,expl:"Reckless navigation = criminal qualification. In French law: 'deliberate endangerment of others'. In English law: 'gross negligence manslaughter' if death results. Conditions: deliberate fault or of such gravity it equates to intent. Examples: navigating wrong-way in TSS for time saving, using autopilot without watch in dense area. Penalty: custodial sentence + permanent certificate revocation."},
  ],
  es:[
    {q:"¿Qué es el 'Tribunal Marítimo' (Marine Court / MAIB)?",opts:["Un tribunal comercial ordinario","Jurisdicción especializada en accidentes marítimos — investiga las causas, extrae lecciones, puede suspender los títulos","Un tribunal de la OMI","Un arbitraje comercial"],correct:1,expl:"Tribunal Marítimo (ej. MAIB UK, BEA-mer Francia, BSU Alemania) = autoridad de investigación de accidentes marítimos. Función: analizar las causas de los accidentes, emitir recomendaciones de seguridad, extraer lecciones. Puede: suspender los títulos, identificar las responsabilidades. Diferente del tribunal penal y del tribunal civil."},
    {q:"¿Qué es el 'CPA' (Closest Point of Approach) en el contexto jurídico COLREG?",opts:["Un acuerdo comercial entre buques","Distancia mínima de acercamiento calculada por radar — si CPA demasiado pequeño = riesgo de abordaje · obligación de actuar (Regla 8)","Un certificado de navegación","Un protocolo de comunicación"],correct:1,expl:"CPA (Closest Point of Approach) = distancia mínima prevista entre dos buques. Calculado por radar ARPA. Si CPA inferior a un umbral seguro = riesgo de abordaje → obligación legal de actuar (COLREG Reglas 7 + 8). En caso de abordaje: el tribunal verifica si se calculó el CPA y si se tomaron acciones. No calcular el CPA = infracción Regla 7 = falta."},
    {q:"¿Cuál es la 'regla de oro' de los abordajes?",opts:["Siempre dar prioridad a los grandes buques","Nunca dudar en maniobrar — la acción tardía es peor que la acción anticipada · el 'último momento' es siempre imperdonable","Siempre reducir la velocidad primero","Llamar por VHF antes de maniobrar"],correct:1,expl:"Regla de oro marítima abordajes: la acción tardía es jurídica y técnicamente peor que la acción anticipada temprana. Un buque que maniobra en el último momento perturba los cálculos del otro. Jurisprudencia: 'demasiado poco, demasiado tarde' = circunstancia agravante. La Regla 8 COLREG exige una maniobra franca, amplia y efectuada a tiempo."},
    {q:"¿Qué es la 'prueba radar' en un procedimiento de abordaje?",opts:["Una foto del radar","Registros radar (ARPA) y AIS conservados tras el accidente — permiten reconstruir las trayectorias e identificar las infracciones COLREG","Un informe escrito del oficial","Un documento de la OMI"],correct:1,expl:"Prueba radar en procedimiento de abordaje: los datos ARPA y AIS son pruebas cruciales. VDR (Registrador de Datos del Viaje) = caja negra marítima conserva 12h de datos. En caso de abordaje: VDR incautado por los investigadores. Permite reconstruir exactamente las trayectorias e identificar quién infringió qué reglas COLREG."},
    {q:"¿Qué es la 'pericia marítima' (marine surveyor) en un procedimiento de abordaje?",opts:["Un inspector PSC","Perito independiente encargado por los aseguradores P&I o los tribunales para evaluar los daños y analizar las causas del abordaje","Un miembro de la OMI","Un experto marítimo comercial"],correct:1,expl:"Marine surveyor = perito marítimo independiente. En caso de abordaje: encargado por Club P&I, asegurador de carga o tribunal. Misiones: evaluar los daños materiales, analizar las causas (infracciones COLREG), reconstruir las trayectorias, elaborar un informe pericial técnico. Su informe es una pieza central del expediente judicial."},
    {q:"¿Qué es el 'derecho de paso inocente' en el contexto COLREG?",opts:["Un acuerdo bilateral","Derecho de los buques extranjeros a atravesar el mar territorial de un Estado (12 millas) sin autorización — a condición de no amenazar la paz","Un derecho comercial","Un derecho de pesca"],correct:1,expl:"Derecho de paso inocente (CONVEMAR Art.17-32) = derecho fundamental. El buque extranjero puede atravesar el mar territorial (12 millas) SIN autorización previa SI: paso continuo y rápido, no perjudicial para la paz y seguridad. COLREG plenamente aplicable durante el paso. El Estado ribereño puede establecer corredores de navegación obligatorios."},
    {q:"¿Qué es la 'limitación de tonelaje' (limitación de responsabilidad) en derecho marítimo?",opts:["Un límite de peso de la carga","Derecho del armador a limitar su responsabilidad civil a un importe basado en el tonelaje del buque — Convenio LLMC 1976","Un límite de velocidad","Un límite de seguro"],correct:1,expl:"Limitación de responsabilidad = Convenio LLMC 1976. El armador puede limitar su responsabilidad a un importe calculado según el tonelaje. Excepciones: falta intencional del propietario. Importancia: incluso para daños de varios millones, el armador puede pagar solo una fracción. El Club P&I suele gestionar el procedimiento."},
    {q:"¿Qué es el 'testimonio del oficial de guardia' como prueba en un abordaje?",opts:["Una prueba sin valor legal","Testimonio crucial pero limitado — el oficial puede invocar su derecho al silencio · sus declaraciones pueden usarse en su contra","Un documento de la OMI","Un simple informe de a bordo"],correct:1,expl:"Testimonio OOW en procedimiento de abordaje = prueba esencial pero arriesgada. El oficial de guardia suele ser el principal testigo. Puede: hacer una declaración, negarse a declarar (derecho al silencio). Sus declaraciones iniciales a los investigadores pueden usarse en su contra en el proceso penal. Recomendación: consultar a un abogado marítimo ANTES de hacer una declaración."},
    {q:"¿Qué es la 'cláusula Himalaya' en el contexto marítimo?",opts:["Una cláusula meteorológica","Extensión de la protección contractual concedida al armador a los oficiales y tripulantes — impide que terceros demanden directamente a la tripulación","Un acuerdo de navegación polar","Un contrato de seguro especial"],correct:1,expl:"Cláusula Himalaya = extensión de la limitación de responsabilidad. Permite a los oficiales y tripulantes beneficiarse de las mismas protecciones que el armador. Sin cláusula Himalaya: un tercero podría demandar directamente al oficial de guardia por infracción COLREG. Con la cláusula: el oficial está protegido por los mismos límites."},
    {q:"¿Qué es la 'prescripción' en derecho marítimo de los abordajes?",opts:["Un medicamento de a bordo","Plazo legal más allá del cual una acción judicial tras un abordaje ya no puede interponerse — generalmente 2 años (Convenio Bruselas 1910)","Un protocolo de navegación","Una regla COLREG"],correct:1,expl:"Prescripción en derecho de abordajes: Convenio Bruselas 1910 = plazo de prescripción de 2 años a partir del abordaje. Después de 2 años = acción judicial inadmisible (salvo excepciones). Importancia para los Clubes P&I: declaración de abordaje INMEDIATA para no perder los plazos."},
    {q:"¿Qué es la 'evitación de abordajes' como obligación legal COLREG?",opts:["Una recomendación de la OMI","Obligación legal de tomar TODAS las medidas necesarias para evitar el abordaje — incluso si ello implica violar temporalmente otra regla COLREG","Un sistema técnico","Un protocolo de comunicación"],correct:1,expl:"Evitación de abordajes = obligación legal absoluta (COLREG Regla 8). El buque DEBE tomar todas las medidas para evitar la colisión, incluso si ello requiere violar temporalmente otra regla. Jurisprudencia: el juez acepta las 'maniobras in extremis' como defensa si la situación fue impuesta por el comportamiento culposo del otro buque."},
    {q:"¿Cuál es la 'responsabilidad de la compañía' por las infracciones COLREG de su capitán?",opts:["La compañía nunca es responsable","La compañía puede ser declarada civilmente responsable si no proporcionó formación, instrucciones, equipos o procedimientos adecuados — responsabilidad ISM","Solo el capitán es responsable","La compañía es siempre 100% responsable"],correct:1,expl:"Responsabilidad compañía por infracciones COLREG: Código ISM (SOLAS IX) = la compañía debe asegurarse de que sus buques y oficiales cumplen las normas. Si infracción COLREG → la compañía puede ser perseguida si no proporcionó: oficiales formados (STCW), procedimientos SMS claros, equipos necesarios. Vínculo COLREG + ISM + STCW = responsabilidad encadenada."},
    {q:"¿Qué es el 'derecho de persecución' relacionado con COLREG?",opts:["Un derecho a navegar rápido","Derecho del Estado ribereño a perseguir en alta mar a un buque que infringió COLREG en sus aguas — la persecución debe ser continua e inmediata","Un derecho aduanero","Un derecho de pesca"],correct:1,expl:"Persecución + COLREG: CONVEMAR Art.111 da al Estado ribereño el derecho a perseguir en alta mar a un buque que violó sus leyes en sus aguas territoriales. La persecución debe: comenzar en aguas territoriales, ser inmediata y continua, cesar si el buque entra en aguas de un tercer Estado."},
    {q:"¿Qué es un 'Lloyd's Open Form' (LOF) en caso de abordaje grave?",opts:["Un formulario de seguros estándar","Contrato de salvamento de urgencia firmado 'no cure no pay' — utilizado cuando un buque está en peligro tras un abordaje · remuneración = % del valor salvado","Un tipo de póliza de seguros","Un formulario de la OMI"],correct:1,expl:"Lloyd's Open Form (LOF) = contrato estándar de salvamento marítimo. Utilizado cuando un buque está en peligro. Principio 'no cure no pay' = el salvador solo cobra si tiene éxito. Remuneración: % del valor salvado, determinado por arbitraje de Lloyd's. Firmado en situación de urgencia. Base jurídica de la mayoría de las operaciones de salvamento tras un abordaje."},
    {q:"¿Qué es la 'navegación imprudente' (reckless navigation) en derecho penal marítimo?",opts:["Una infracción civil menor","Calificación penal agravada cuando un oficial navega con una imprudencia tan grave que supera la simple negligencia — conlleva acciones penales personales","Una infracción administrativa","Una regla COLREG"],correct:1,expl:"Navegación imprudente = calificación penal. En derecho francés: 'puesta en peligro deliberada de terceros'. En derecho inglés: 'gross negligence manslaughter' si hay muertos. Condiciones: falta deliberada o de tal gravedad que se asimila a la intención. Ejemplos: navegar en sentido contrario en ZTS para ganar tiempo, usar el piloto automático sin vigilancia en zona densa. Pena: prisión efectiva + retirada definitiva del título."},
  ],
  pt:[
    {q:"O que é o 'Tribunal Marítimo' (Marine Court / MAIB)?",opts:["Um tribunal comercial ordinário","Jurisdição especializada em acidentes marítimos — investiga causas, tira lições, pode suspender certificados","Um tribunal da IMO","Uma arbitragem comercial"],correct:1,expl:"Tribunal Marítimo (ex. MAIB UK, BEA-mer França, BSU Alemanha) = autoridade de investigação de acidentes marítimos. Função: analisar causas dos acidentes, emitir recomendações de segurança, tirar lições. Pode: suspender certificados, identificar responsabilidades. Diferente do tribunal penal e do tribunal civil."},
    {q:"O que é o 'CPA' (Closest Point of Approach) no contexto jurídico COLREG?",opts:["Um acordo comercial entre navios","Distância mínima de aproximação calculada pelo radar — se CPA muito pequeno = risco de abalroamento · obrigação de agir (Regra 8)","Um certificado de navegação","Um protocolo de comunicação"],correct:1,expl:"CPA (Closest Point of Approach) = distância mínima prevista entre dois navios. Calculado pelo radar ARPA. Se CPA abaixo de um limiar seguro = risco de abalroamento → obrigação legal de agir (COLREG Regras 7 + 8). Em caso de abalroamento: o tribunal verifica se o CPA foi calculado e se foram tomadas ações. Não calcular o CPA = violação Regra 7 = falta."},
    {q:"Qual é a 'regra de ouro' dos abalroamentos?",opts:["Dar sempre prioridade aos navios grandes","Nunca hesitar em manobrar — a ação tardia é pior que a ação antecipada · o 'último momento' é sempre imperdoável","Reduzir sempre a velocidade primeiro","Chamar no VHF antes de manobrar"],correct:1,expl:"Regra de ouro marítima abalroamentos: a ação tardia é legal e tecnicamente pior do que a ação antecipada. Um navio que manobra no último momento perturba os cálculos do outro. Jurisprudência: 'demasiado pouco, demasiado tarde' = circunstância agravante. A Regra 8 COLREG exige uma manobra franca, ampla e efetuada cedo."},
    {q:"O que é a 'prova de radar' num processo de abalroamento?",opts:["Uma foto do radar","Registos radar (ARPA) e AIS conservados após o acidente — permitem reconstruir as trajetórias e identificar as violações COLREG","Um relatório escrito do oficial","Um documento da IMO"],correct:1,expl:"Prova de radar em processo de abalroamento: os dados ARPA e AIS são provas cruciais. VDR (Registador de Dados da Viagem) = caixa negra marítima conserva 12h de dados. Em caso de abalroamento: VDR apreendido pelos investigadores. Permite reconstruir exatamente as trajetórias e identificar quem violou que regras COLREG."},
    {q:"O que é a 'peritagem marítima' (marine surveyor) num processo de abalroamento?",opts:["Um inspetor PSC","Perito independente mandatado pelos seguradores P&I ou tribunais para avaliar os danos e analisar as causas do abalroamento","Um membro da IMO","Um perito marítimo comercial"],correct:1,expl:"Marine surveyor = perito marítimo independente. Em caso de abalroamento: mandatado pelo P&I Club, segurador de carga ou tribunal. Missões: avaliar os danos materiais, analisar as causas (violações COLREG), reconstruir as trajetórias, elaborar um relatório pericial técnico. O seu relatório é peça central do processo judicial."},
    {q:"O que é o 'direito de passagem inocente' no contexto COLREG?",opts:["Um acordo bilateral","Direito dos navios estrangeiros de atravessar o mar territorial de um Estado (12 milhas) sem autorização — desde que não ameacem a paz","Um direito comercial","Um direito de pesca"],correct:1,expl:"Direito de passagem inocente (UNCLOS Art.17-32) = direito fundamental. O navio estrangeiro pode atravessar o mar territorial (12 milhas) SEM autorização prévia SE: passagem contínua e rápida, não prejudicial para a paz e segurança. COLREG plenamente aplicável durante a passagem. O Estado costeiro pode estabelecer corredores de navegação obrigatórios."},
    {q:"O que é a 'limitação de tonelagem' (limitação de responsabilidade) no direito marítimo?",opts:["Um limite de peso da carga","Direito do armador de limitar a responsabilidade civil a um montante baseado na tonelagem do navio — Convenção LLMC 1976","Um limite de velocidade","Um limite de seguro"],correct:1,expl:"Limitação de responsabilidade = Convenção LLMC 1976. O armador pode limitar a responsabilidade a um montante calculado pela tonelagem. Exceções: falta intencional do proprietário. Importância: mesmo para danos de vários milhões, o armador pode pagar apenas uma fração. O P&I Club gere frequentemente o procedimento."},
    {q:"O que é o 'testemunho do oficial de quarto' como prova num abalroamento?",opts:["Uma prova sem valor legal","Testemunho crucial mas limitado — o oficial pode invocar o direito ao silêncio · as suas declarações podem ser usadas contra ele","Um documento da IMO","Um simples relatório de bordo"],correct:1,expl:"Testemunho OOW em processo de abalroamento = prova essencial mas arriscada. O oficial de quarto é frequentemente a principal testemunha. Pode: fazer uma declaração, recusar-se a testemunhar (direito ao silêncio). As declarações iniciais aos investigadores podem ser usadas contra ele no processo penal. Recomendação: consultar advogado marítimo ANTES de fazer uma declaração."},
    {q:"O que é a 'cláusula Himalaia' no contexto marítimo?",opts:["Uma cláusula meteorológica","Extensão da proteção contratual concedida ao armador aos oficiais e tripulantes — impede terceiros de processar diretamente a tripulação","Um acordo de navegação polar","Um contrato de seguro especial"],correct:1,expl:"Cláusula Himalaia = extensão da limitação de responsabilidade. Permite aos oficiais e tripulantes beneficiar das mesmas proteções que o armador. Sem cláusula Himalaia: um terceiro poderia processar diretamente o oficial de quarto por violação COLREG. Com a cláusula: o oficial é protegido pelos mesmos limites."},
    {q:"O que é a 'prescrição' no direito marítimo dos abalroamentos?",opts:["Um medicamento de bordo","Prazo legal além do qual uma ação judicial após abalroamento já não pode ser intentada — geralmente 2 anos (Convenção Bruxelas 1910)","Um protocolo de navegação","Uma regra COLREG"],correct:1,expl:"Prescrição em direito dos abalroamentos: Convenção Bruxelas 1910 = prazo de prescrição de 2 anos a partir do abalroamento. Após 2 anos = ação judicial inadmissível (com exceções). Importância para P&I Clubs: declaração de abalroamento IMEDIATA para não perder os prazos."},
    {q:"O que é a 'evitação de abalroamentos' como obrigação legal COLREG?",opts:["Uma recomendação da IMO","Obrigação legal de tomar TODAS as medidas necessárias para evitar o abalroamento — mesmo que isso implique violar temporariamente outra regra COLREG","Um sistema técnico","Um protocolo de comunicação"],correct:1,expl:"Evitação de abalroamentos = obrigação legal absoluta (COLREG Regra 8). O navio DEVE tomar todas as medidas para evitar o abalroamento, mesmo que seja necessário violar temporariamente outra regra. Jurisprudência: o juiz aceita as 'manobras in extremis' como defesa se a situação foi imposta pelo comportamento faltoso do outro navio."},
    {q:"Qual é a 'responsabilidade da companhia' pelas violações COLREG do seu capitão?",opts:["A companhia nunca é responsável","A companhia pode ser considerada civilmente responsável se não forneceu formação, instruções, equipamentos ou procedimentos adequados — responsabilidade ISM","Apenas o capitão é responsável","A companhia é sempre 100% responsável"],correct:1,expl:"Responsabilidade companhia por violações COLREG: Código ISM (SOLAS IX) = a companhia deve garantir que os seus navios e oficiais cumprem as regras. Se violação COLREG → a companhia pode ser processada se não forneceu: oficiais formados (STCW), procedimentos SMS claros, equipamentos necessários. Ligação COLREG + ISM + STCW = responsabilidade encadeada."},
    {q:"O que é o 'direito de perseguição' relacionado com o COLREG?",opts:["Um direito de navegar rápido","Direito do Estado costeiro de perseguir em alto mar um navio que violou o COLREG nas suas águas — a perseguição deve ser contínua e imediata","Um direito aduaneiro","Um direito de pesca"],correct:1,expl:"Perseguição + COLREG: UNCLOS Art.111 dá ao Estado costeiro o direito de perseguir em alto mar um navio que violou as suas leis nas suas águas territoriais. A perseguição deve: começar nas águas territoriais, ser imediata e contínua, cessar se o navio entrar nas águas de um terceiro Estado."},
    {q:"O que é um 'Lloyd's Open Form' (LOF) em caso de abalroamento grave?",opts:["Um formulário de seguro padrão","Contrato de salvamento de emergência assinado 'no cure no pay' — usado quando um navio está em perigo após abalroamento · remuneração = % do valor salvo","Um tipo de apólice de seguro","Um formulário da IMO"],correct:1,expl:"Lloyd's Open Form (LOF) = contrato padrão de salvamento marítimo. Usado quando um navio está em perigo. Princípio 'no cure no pay' = o salvador só é pago se tiver sucesso. Remuneração: % do valor salvo, determinado por arbitragem Lloyd's. Assinado em situação de emergência. Base jurídica da maioria das operações de salvamento após abalroamento."},
    {q:"O que é a 'navegação imprudente' (reckless navigation) no direito penal marítimo?",opts:["Uma infração civil menor","Qualificação penal agravada quando um oficial navega com imprudência tão grave que ultrapassa a simples negligência — leva a processos penais pessoais","Uma infração administrativa","Uma regra COLREG"],correct:1,expl:"Navegação imprudente = qualificação penal. Em direito francês: 'colocação em perigo deliberada de terceiros'. Em direito inglês: 'gross negligence manslaughter' se houver mortos. Condições: falta deliberada ou de tal gravidade que se equipara à intenção. Exemplos: navegar no sentido errado em ZST para ganhar tempo, usar o piloto automático sem vigilância em zona densa. Pena: prisão efetiva + revogação definitiva do certificado."},
  ],
};

function QuestionBank({ lang }) {
  const [cur,setCur]=useState(0);const [sel,setSel]=useState(null);const [answered,setAnswered]=useState(false);const [score,setScore]=useState(0);const [done,setDone]=useState(false);
  const questions=BANK[lang]||BANK.fr;const [shuffled]=useState(()=>questions.map(shuffleQuestionOptions));const q=shuffled[cur];const isOk=sel===q.correct;
  const pick=i=>{if(answered)return;setSel(i);setAnswered(true);if(i===q.correct)setScore(s=>s+1);};
  const next=()=>{if(cur<questions.length-1){setCur(c=>c+1);setSel(null);setAnswered(false);}else setDone(true);};
  if(done)return(<div style={{textAlign:"center",padding:"20px 0"}}><div style={{fontSize:48}}>{score>=12?"🏆":score>=8?"🎖️":"📚"}</div><div style={{fontFamily:"'Cinzel',serif",fontSize:20,color:C.white,margin:"8px 0 4px"}}>{score}/{questions.length}</div><div style={{fontSize:14,color:C.gold2}}>{Math.round(score/questions.length*100)}%</div></div>);
  return(<div>
    <div style={{display:"flex",justifyContent:"space-between",marginBottom:10}}><div style={{fontSize:10,color:C.muted}}>{cur+1}/{questions.length}</div><div style={{fontSize:12,color:C.gold2,fontWeight:700}}>✓ {score}</div></div>
    <div style={{height:3,background:"rgba(255,255,255,0.08)",borderRadius:3,marginBottom:12,overflow:"hidden"}}><div style={{height:"100%",width:`${(cur/questions.length)*100}%`,background:`linear-gradient(90deg,${C.blue2},${C.gold2})`}}/></div>
    <div style={{fontSize:13,fontWeight:700,color:C.white,lineHeight:1.5,marginBottom:12}}>{q.q}</div>
    <div style={{display:"flex",flexDirection:"column",gap:8,marginBottom:10}}>
      {q.opts.map((opt,i)=>{let bg="rgba(255,255,255,0.05)",bd="rgba(255,255,255,0.1)";if(answered){if(i===q.correct){bg="rgba(30,138,74,0.2)";bd=C.green;}else if(i===sel){bg="rgba(192,57,43,0.2)";bd=C.red;}}return<button key={i} onClick={()=>pick(i)} style={{padding:"10px 12px",borderRadius:12,background:bg,border:`1.5px solid ${bd}`,color:C.muted,fontSize:12,textAlign:"left",cursor:answered?"default":"pointer",lineHeight:1.4}}>{opt}</button>;})}
    </div>
    {answered&&<><div style={{padding:"10px 12px",borderRadius:10,marginBottom:10,background:isOk?"rgba(30,138,74,0.12)":"rgba(192,57,43,0.1)",border:`1px solid ${isOk?C.green:C.red}44`,fontSize:11,color:C.white,lineHeight:1.6}}>{q.expl}</div>
    <button onClick={next} style={{width:"100%",padding:"11px 0",border:"none",borderRadius:12,background:`linear-gradient(135deg,${C.blue2},${C.gold2})`,fontFamily:"'Cinzel',serif",fontSize:12,fontWeight:700,letterSpacing:2,color:C.white,cursor:"pointer"}}>{cur<questions.length-1?(lang==="fr"?"SUIVANT →":lang==="en"?"NEXT →":lang==="es"?"SIGUIENTE →":"PRÓXIMO →"):(lang==="fr"?"TERMINER":lang==="en"?"FINISH":lang==="es"?"TERMINAR":"TERMINAR")}</button></>}
  </div>);
}

function Stars(){const s=Array.from({length:14},()=>({x:Math.random()*100,y:Math.random()*100,sz:Math.random()>0.7?2:1.5,dur:2+Math.random()*4,delay:Math.random()*6}));return(<><div style={{position:"fixed",inset:0,pointerEvents:"none",zIndex:0}}>{s.map((st,i)=><div key={i} style={{position:"absolute",left:`${st.x}%`,top:`${st.y}%`,width:st.sz,height:st.sz,borderRadius:"50%",background:"white",opacity:0,animation:`tw ${st.dur}s ease-in-out ${st.delay}s infinite`}}/>)}</div><style>{`@keyframes tw{0%,100%{opacity:0}50%{opacity:0.35}}@keyframes fadeUp{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:translateY(0)}}@keyframes correctPop{0%{transform:scale(0.85)}60%{transform:scale(1.1)}100%{transform:scale(1)}}@keyframes wrongShake{0%,100%{transform:translateX(0)}25%{transform:translateX(-5px)}75%{transform:translateX(5px)}}`}</style></>);}
function Card({children,style={}}){return<div style={{background:"rgba(13,31,60,0.75)",border:`1px solid ${C.border}`,borderRadius:18,padding:"16px",...style}}>{children}</div>;}
function GLine(){return<div style={{height:1,margin:"14px 0",background:`linear-gradient(90deg,transparent,${C.blue2}33,${C.gold2}33,transparent)`}}/>;}
function SL({icon,text,color}){return<div style={{display:"flex",alignItems:"center",gap:10,margin:"20px 0 12px"}}><span style={{fontSize:20}}>{icon}</span><div style={{fontFamily:"'Cinzel',serif",fontSize:12,fontWeight:700,color:color||C.gold,letterSpacing:2}}>{text}</div><div style={{flex:1,height:1,background:`linear-gradient(90deg,${color||C.gold}44,transparent)`}}/></div>;}

function QuizComp({questions,t,onComplete}){
  const [shuffled]=useState(()=>questions.map(shuffleQuestionOptions));
  const [cur,setCur]=useState(0);const [sel,setSel]=useState(null);const [answered,setAnswered]=useState(false);const [score,setScore]=useState(0);const [answers,setAnswers]=useState([]);const [done,setDone]=useState(false);
  const q=shuffled[cur];const isOk=sel===q.correct;
  const pick=i=>{if(answered)return;setSel(i);setAnswered(true);if(i===q.correct)setScore(s=>s+1);setAnswers(a=>[...a,{i,ok:i===q.correct}]);};
  const next=()=>{if(cur<questions.length-1){setCur(c=>c+1);setSel(null);setAnswered(false);}else{setDone(true);onComplete(score+(isOk?1:0));}};
  if(done){const fs=score;const pct=Math.round(fs/questions.length*100);const xp=fs>=4?200:fs===3?120:60;return(<Card style={{textAlign:"center"}}><div style={{fontSize:52,marginBottom:8}}>{pct===100?"🏆":pct>=80?"🎖️":"📚"}</div><div style={{fontFamily:"'Cinzel',serif",fontSize:28,fontWeight:900,color:C.white,marginBottom:4}}>{fs}/{questions.length}</div><div style={{display:"inline-block",marginTop:8,padding:"6px 16px",borderRadius:20,background:"rgba(201,146,42,0.15)",border:`1px solid ${C.gold}44`,fontSize:14,color:C.gold2,fontWeight:700}}>+{xp} {t.xp} ⭐</div><GLine/><div style={{display:"flex",justifyContent:"center",gap:8,marginTop:8}}>{answers.map((a,i)=><div key={i} style={{width:32,height:32,borderRadius:"50%",background:a.ok?C.green:C.red,display:"flex",alignItems:"center",justifyContent:"center",fontSize:14,color:C.white}}>{a.ok?"✓":"✗"}</div>)}</div></Card>);}
  return(<Card style={{border:`1px solid ${C.blue2}33`}}><div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:14}}><div style={{fontSize:11,letterSpacing:3,color:C.blue2,fontFamily:"'Cinzel',serif"}}>{t.quiz}</div><div style={{fontSize:12,color:C.muted}}>{t.question} {cur+1} {t.ofQ} {questions.length}</div></div><div style={{display:"flex",gap:6,marginBottom:16}}>{questions.map((_,i)=><div key={i} style={{flex:1,height:3,borderRadius:3,background:i<cur?(answers[i]?.ok?C.green:C.red):i===cur?C.blue2:"rgba(255,255,255,0.1)"}}/>)}</div><div style={{fontSize:14,fontWeight:700,color:C.white,lineHeight:1.5,marginBottom:16}}>{q.q}</div><div style={{display:"flex",flexDirection:"column",gap:10,marginBottom:14}}>{q.opts.map((opt,i)=>{let bg="rgba(255,255,255,0.05)",bd="rgba(255,255,255,0.1)",anim="none";if(answered){if(i===q.correct){bg="rgba(30,138,74,0.2)";bd=C.green;anim="correctPop 0.4s ease";}else if(i===sel){bg="rgba(192,57,43,0.2)";bd=C.red;anim="wrongShake 0.4s ease";}}return<button key={i} onClick={()=>pick(i)} style={{padding:"12px 14px",borderRadius:14,background:bg,border:`1.5px solid ${bd}`,color:answered&&(i===q.correct||i===sel)?C.white:C.muted,fontSize:13,textAlign:"left",cursor:answered?"default":"pointer",animation:anim,display:"flex",alignItems:"center",gap:10,lineHeight:1.4}}><div style={{width:26,height:26,borderRadius:"50%",flexShrink:0,background:answered&&i===q.correct?C.green:answered&&i===sel?C.red:"rgba(255,255,255,0.1)",display:"flex",alignItems:"center",justifyContent:"center",fontSize:12,fontWeight:700,color:C.white}}>{answered&&i===q.correct?"✓":answered&&i===sel?"✗":String.fromCharCode(65+i)}</div><span>{opt}</span></button>;})} </div>{answered&&<div style={{padding:"12px 14px",borderRadius:12,marginBottom:14,background:isOk?"rgba(30,138,74,0.12)":"rgba(192,57,43,0.1)",border:`1px solid ${isOk?C.green:C.red}44`,animation:"fadeUp 0.4s ease"}}><div style={{fontSize:12,fontWeight:700,marginBottom:4,color:isOk?C.green:C.red}}>{isOk?t.correct:t.wrong}</div><div style={{fontSize:11,color:C.muted,fontWeight:600,marginBottom:2}}>{t.expl}</div><div style={{fontSize:12,color:C.white,lineHeight:1.6}}>{q.expl}</div></div>}{answered&&<button onClick={next} style={{width:"100%",padding:"14px 0",border:"none",borderRadius:14,background:`linear-gradient(135deg,${C.blue2},${C.gold})`,fontFamily:"'Cinzel',serif",fontSize:13,fontWeight:700,letterSpacing:2,color:C.white,cursor:"pointer"}}>{cur<questions.length-1?t.next:t.finish}</button>}</Card>);
}

